NAME = 'ACV: A Conservative Version'
BOOK = 'Leviticus'

CHAPTERS = {
    1: {
        1: 'In pokliče Gospod Mojzesa in mu govori iz shodnega šatora, rekoč:',
        2: 'Govóri sinovom Izraelovim in jim reci: Če hoče kdo izmed vas prinesti darilo Gospodu, od živine, od govedi ali drobnice, prinesite darilo svoje.',
        3: 'Čigar darilo je v žgalno daritev od govedi, naj prinese samca brez hibe; pri vhodu shodnega šatora naj ga daruje, da bo milo sprejet pred Gospodom.',
        4: 'In položi naj roko svojo na glavo žgalne žrtve, da bo milo sprejeta za njega, v poravnavo zanj.',
        5: 'In zakolje naj tisto mlado govedo pred Gospodom; in prineso sinovi Aronovi, duhovniki, kri njegovo in ž njo poškropé kroginkrog oltar, ki je proti vhodu v shodni šator.',
        6: 'In odere žgalno daritev in jo razseka v njene kose.',
        7: 'In sinovi Arona duhovnika denejo ogenj na oltar in polože drva na ogenj.',
        8: 'Potem naj sinovi Aronovi, duhovniki, polože te kose, glavo in tolščobo na drva nad ognjem vrh oltarja.',
        9: 'Njegovo drobje pa in noge njegove naj se opero v vodi; in duhovnik naj zažge vse to na oltarju: žgalna daritev je, ognjena žrtev v prijeten duh Gospodu.',
        10: 'Če pa je darilo njegovo drobnica, od ovac ali koz, v žgalno daritev, prinese naj samca brez hibe.',
        11: 'In naj ga zakolje na polnočni strani oltarja pred Gospodom; in razškrope naj sinovi Aronovi, duhovniki, kri njegovo po oltarju kroginkrog.',
        12: 'In naj ga razseka v kose njegove z glavo in tolščo njegovo, in duhovnik jih polóži na drva nad ognjem vrh oltarja.',
        13: 'Drobje pa in noge naj umije z vodo, in duhovnik naj vse to daruje in zapali na oltarju: žgalna daritev je, ognjena žrtev v prijeten duh Gospodu.',
        14: 'Ako pa je darilo njegovo ptica v žgalščino Gospodu, naj prinese grlico ali golobčka za darilo svoje.',
        15: 'In duhovnik prinesi ptico k oltarju in ji odščipni z nohtom glavico in jo zažgi na oltarju, njena kri pa naj se iztisne na oltarjevo steno.',
        16: 'Golžun in nesnago njeno pa naj odpravi ter vrže to poleg oltarja na vzhodno stran na pepelišče.',
        17: 'In naj jo nakrhne ob krilih, ne da bi jo pretrgal, in duhovnik naj jo zažge na oltarju, na drvih, ki so na ognju: žgalna daritev je, žrtev po ognju v prijeten duh Gospodu.',
    },
    2: {
        1: 'Če pa hoče kdo prinesti darilo jedilne žrtve Gospodu, bela moka bodi darilo njegovo, in naj vlije olja nanjo in dene nanjo kadila',
        2: 'in jo prinese sinovom Aronovim, duhovnikom; in duhovnik naj vzame prgišče tega, moke in olja z vsem kadilom njenim, in naj to sežge na oltarju kot njen spomin: ognjena žrtev je v prijeten duh Gospodu.',
        3: 'Kar pa ostane jedilne daritve, bodi Aronovo in sinov njegovih: presveto je od ognjenih žrtev Gospodovih.',
        4: 'Če pa hočeš prinesti v darilo jedilne žrtve kaj v peči pečenega, naj bodo opresni kolači iz bele moke, zamešeni z oljem, ali pa opresni mlinci, pomazani z oljem.',
        5: 'Ako je pa darilo tvoje jedilna žrtev, pečena v ponvi, naj bode iz bele moke, zamešena z oljem, brez kvasu.',
        6: 'Zdrobi jo v grižljaje in vlij nanjo olja: jedilna daritev je.',
        7: 'Ako je pa darilo tvoje jedilna žrtev, skuhana v kotlu, bodi pripravljena iz bele moke z oljem.',
        8: 'In prinesi jedilno daritev, ki si jo iz tega pripravil, Gospodu, in podaj jo duhovniku, in on pristopi ž njo k oltarju.',
        9: 'In duhovnik naj vzame od jedilne daritve, kar je v njen spomin, in to zažge na oltarju: ognjena žrtev je v prijeten duh Gospodu.',
        10: 'Kar pa ostane jedilne daritve, bodi Aronovo in sinov njegovih: presveto je od ognjenih daritev Gospodovih.',
        11: 'Nobene jedilne daritve, ki jo prinesete Gospodu, ne pripravljajte s kvasom; kajti ničesar od kvasu, ne od medu ne smete žgati v žrtev Gospodu po ognju.',
        12: 'Kot daritev prvin jih smete prinesti Gospodu, a na oltar naj se ne pokladajo v prijeten duh.',
        13: 'In sleherno darilo jedilne žrtve svoje osoli in ne daj, da bi zmanjkalo soli zaveze Boga tvojega pri jedilnih daritvah tvojih: z vsemi darili svojimi daruj soli.',
        14: 'In če hočeš prinesti Gospodu jedilno daritev od prvin, daruj zrnja v klasju, opraženega na ognju, zrnja raztolčenega, kot jedilno daritev od prvin svojih.',
        15: 'In vlij nanje olja in deni nanje kadila: jedilna daritev je.',
        16: 'In duhovnik naj sežge del zrnja raztolčenega in del olja z vsem kadilom njegovim kot njen spomin: ognjena žrtev je Gospodu.',
    },
    3: {
        1: 'In čigar darilo je mirovna žrtev: ako daruje govedo, bodisi samec ali samica, brezhibno naj prinese pred Gospoda.',
        2: 'In položi naj roko svojo na glavo darila svojega in ga zakolje pri vhodu shodnega šatora; in sinovi Aronovi, duhovniki, naj poškrope s krvjo oltar kroginkrog.',
        3: 'In del mirovne daritve naj daruje kot ognjeno žrtev Gospodu, namreč tolstino, ki pokriva drobje, in karkoli je tolsti na črevih,',
        4: 'in obe ledici in tolst, ki je na njiju, ki je na obledju, in pečico na jetrih: z ledicami vred naj to odreže.',
        5: 'In zažgo naj to sinovi Aronovi na oltarju nad žgalno daritvijo na drvih, ki so na ognju: ognjena žrtev je v prijeten duh Gospodu.',
        6: 'Ako pa je od drobnice darilo njegovo, Gospodu v mirovno daritev, bodisi samec ali samica, brezhibno naj prinese.',
        7: 'Če pokloni ovco v darilo svoje, naj jo daruje pred Gospodom;',
        8: 'in položi naj roko na glavo darila svojega in ga zakolje pred shodnim šatorom; in poškrope naj sinovi Aronovi s krvjo oltar kroginkrog.',
        9: 'In daruj del mirovne daritve kot ognjeno žrtev Gospodu: njeno mast, ves tolsti rep, ki ga odreže tik hrbtenice, in tolstino, ki pokriva drobje, in vso tolstino na črevih,',
        10: 'in obe ledici in tolst, ki je na njiju, ki je na obledju, in pečico na jetrih: z ledicami vred naj to odreže.',
        11: 'In zažge naj to duhovnik na oltarju: živež je daritve po ognju Gospodu.',
        12: 'Ako je koza njegovo darilo, naj jo daruje pred Gospodom;',
        13: 'in naj ji položi roko svojo na glavo in jo zakolje pred shodnim šatorom; in sinovi Aronovi naj škrope njeno kri po oltarju naokrog.',
        14: 'In del od nje naj prinese v darilo svoje kot ognjeno žrtev Gospodu: tolstino, ki pokriva drobje, in karkoli je tolstine na črevih,',
        15: 'in obe ledici in tolst, ki je na njiju, ki je na obledju, in pečico na jetrih: z ledicami vred naj to odreže.',
        16: 'In zažge naj to duhovnik na oltarju: živež je ognjene daritve v prijeten duh; vsa tolstina bodi Gospodova.',
        17: 'Večna bodi to postava prihodnjim rodovom vašim po vseh prebivališčih vaših: ne tolstine, ne krvi nikar ne uživajte!',
    },
    4: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'Govóri sinovom Izraelovim in véli: Če se kdo pregreši po pomoti v čemerkoli, za kar je Gospod zapovedal, da se ne sme storiti, pa storí kaj takega:',
        3: 'če se pregreši pomaziljeni duhovnik, tako da spravi krivdo nad ljudstvo, naj daruje za svoj greh, ki ga je zagrešil, mladega junca brez hibe Gospodu v daritev za greh.',
        4: 'In naj privede junca k vhodu shodnega šatora pred Gospoda in mu položi roko na glavo in ga zakolje pred Gospodom.',
        5: 'In pomaziljeni duhovnik vzemi nekoliko krvi in jo nesi v shodni šator,',
        6: 'in naj si omoči prst v krvi in škropi ž njo sedemkrat pred Gospodom, proti zagrinjalu svetišča.',
        7: 'In dene naj duhovnik nekaj krvi na rogove oltarja blagodišečih kadil pred Gospodom, ki je v shodnem šatoru; in vso ostalo junčevo kri naj izlije v znožje oltarja žgalnih daritev, ki je proti vhodu v shodni šator.',
        8: 'In vso tolstino junca, darovanega za greh, naj pobere ž njega: tolstino, ki pokriva drobje, in karkoli je tolstine na črevih,',
        9: 'in obe ledici in tolst, ki je na njiju, ki je na obledju, in pečico na jetrih: z ledicami vred naj to odreže,',
        10: 'kakor se jemlje od goveda mirovne daritve; in duhovnik naj to zažge na oltarju žgalnih daritev.',
        11: 'Kožo pa junčevo in vse meso njegovo z glavo, z nogami in drobom in blatom njegovim:',
        12: 'vsega junca naj odneso ven iz taborišča na čist kraj, kamor se siplje pepel, in sežgo naj ga na drvih z ognjem; na pepelišču naj ga sežgo.',
        13: 'In če se vsa občina Izraelova pregreši po pomoti in stvar bi bila prikrita očem zbora, in učinili so, kar je Gospod zapovedal, da se storiti ne sme, in so krivi:',
        14: 'ko spoznajo greh, s katerim so grešili, tedaj naj daruje zbor mladega junca v daritev za greh in ga privede pred shodni šator.',
        15: 'In položé naj starejšine občine juncu roke na glavo pred Gospodom in naj ga zakoljejo pred Gospodom.',
        16: 'In pomaziljeni duhovnik naj nese junčeve krvi v shodni šator,',
        17: 'in pomoči naj si prst v kri in škropi sedemkrat pred Gospodom proti zagrinjalu.',
        18: 'In deni nekoliko krvi na rogove oltarja, ki je pred Gospodom v shodnem šatoru; in vso drugo kri naj izlije v znožje oltarja žgalnih daritev, ki je proti vhodu v shodni šator.',
        19: 'In vso tolstino naj pobere ž njega in jo zažge na oltarju.',
        20: 'In naredi naj z juncem, kakor je naredil z juncem daritve za greh: prav tako naj ž njim stori. In tako naj izvrši duhovnik poravnavo zanje, in bode jim odpuščeno.',
        21: 'In junca naj odneso ven iz šatorišča in ga sežgo, kakor so sežgali prvega junca: daritev za greh je to zboru.',
        22: 'Ko se pregreši knez in stori po pomoti katerokoli reč, ki je zanjo zapovedal Gospod, njegov Bog, da se storiti ne sme, in je kriv:',
        23: 'kadar mu pride na vest greh, s katerim je grešil, naj prinese kozla, brezhibnega samca.',
        24: 'In naj položi kozlu roko na glavo in ga zakolje na mestu, kjer koljejo žgalne daritve pred Gospodom: daritev za greh je.',
        25: 'In duhovnik vzemi s prstom krvi daritve za greh in jo deni na rogove žgalnega oltarja, in ostalo kri izlij v znožje žgalnega oltarja.',
        26: 'In vso tolstino njegovo naj sežge na oltarju, kakor tolst daritev mirovnih. In tako naj izvrši duhovnik poravnavo zanj zaradi njegovega greha, in bo mu odpuščeno.',
        27: 'Ako pa se pregreši kdo iz preprostega ljudstva po pomoti in stori zoper eno izmed prepovedi Gospodovih, kar se ne sme storiti, in je kriv:',
        28: 'kadar mu pride na vest greh, s katerim je grešil, naj prinese darilo svoje, kozo brez hibe, samico, za greh svoj, ki ga je zakrivil.',
        29: 'In položi naj roko na glavo daritve za greh in zakolje daritev za greh na kraju za žgalščine.',
        30: 'In duhovnik vzemi njene krvi s prstom in jo deni na rogove žgalnega oltarja, in vso ostalo kri njeno izlij v znožje oltarja.',
        31: 'In odreže naj vso tolst njeno, kakor se odreže od daritev mirovnih; in duhovnik naj jo zažge na oltarju v prijeten duh Gospodu. In tako naj izvrši duhovnik poravnavo zanj, in bo mu odpuščeno.',
        32: 'Če pa prinese ovco kot darilo svoje v žrtev za greh, naj bode brez hibe samica, ki jo bo daroval.',
        33: 'In položi naj roko na glavo daritvi za greh in jo zakolje za greh na kraju, kjer se navadno koljejo žgalščine.',
        34: 'In duhovnik vzemi krvi daritve za greh s prstom in jo deni na rogove žgalnega oltarja, in vso ostalo kri njeno izlij v znožje oltarja.',
        35: 'In vso tolstino njeno naj odreže, kakor se odreže tolst od ovce daritve mirovne; in duhovnik naj jo zažge na oltarju, na ognjenih daritvah Gospodu. In tako naj izvrši duhovnik poravnavo zanj, za greh njegov, in bo mu odpuščeno.',
    },
    5: {
        1: 'In če se kdo pregreši s tem, da čuje glas zaprisege, in sam je bil priča, bodi da je stvar videl ali zvedel, pa ničesar ne izpove, bo nosil krivico svojo;',
        2: 'ali pa če se kdo dotakne česa nečistega, bodi mrhovine nečiste zveri, ali mrhovine nečiste živali, ali mrhovine nečiste laznine, čeprav mu je prikrito, vendar je nečist in kriv;',
        3: 'ali pa če se dotakne nečistosti človeka, najsi bo kakršnakoli nečistost njegova, s katero se onečisti, in mu je prikrito, kadar pa zazna, je kriv;',
        4: 'ali pa če kdo priseže, nepremišljeno govoreč z usti svojimi, da stori zlo ali dobro, o čemerkoli človek lahko govori nepremišljeno s prisego, in mu je prikrito, kadar pa spozna, kriv je ene teh reči:',
        5: 'če je torej kriv česa takega, naj pripozna, s čimer je grešil,',
        6: 'in prinese naj daritev za krivdo Gospodu za greh, s katerim se je pregrešil: samico iz drobnice, ovco ali kozo, v daritev za greh; in duhovnik naj izvrši poravnavo zanj, zaradi greha njegovega.',
        7: 'Če pa imetje njegovo ni zadostno za ovco, naj prinese za svojo krivdo, s katero se je pregrešil, dve grlici ali dva golobiča Gospodu, enega za greh, enega pa v žgalno daritev.',
        8: 'In prinese naj ju k duhovniku, ki naj daruje tistega, ki je v daritev za greh, najprej in mu odščipne glavico tik zatilnika, ne da bi jo odtrgal.',
        9: 'In škropi naj kri daritve za greh na oltarjevo steno, in ostala kri naj se iztisne v znožje oltarja: daritev je za greh.',
        10: 'Drugega pa naj pripravi v žgalno daritev, po predpisu. In tako naj izvrši duhovnik poravnavo zanj, zaradi greha njegovega, s katerim je grešil, in bo mu odpuščeno.',
        11: 'Ako pa ne premore dveh grlic ali dveh golobičev, naj prinese tisti, ki je grešil, za svoje darilo desetino efe bele moke v daritev za greh; ne vlije pa naj olja nanjo in ne dene kadila nanjo, ker daritev za greh je.',
        12: 'In naj jo prinese k duhovniku, in duhovnik je vzemi prgišče kot njen spomin, in zažge naj to na oltarju, na ognjenih daritvah Gospodu: daritev za greh je.',
        13: 'In tako naj izvrši duhovnik poravnavo zanj, za njegov greh, ki ga je zagrešil v katerikoli teh reči, in bo mu odpuščeno; in kar preostane, bodi duhovnikovo kakor jedilna daritev.',
        14: 'In Gospod je govoril Mojzesu, rekoč:',
        15: 'Če kdo zakrivi iznevero in se ponevedoma pregreši pri tem, kar je sveto Gospodu, naj prinese daritev za krivdo Gospodu, ovna brez hibe izmed črede, po cenitvi tvoji v seklih srebrnih, po seklu svetišča, v daritev za krivdo.',
        16: 'In kolikor je zagrešil škode pri svetem, naj povrne in peti del še pridene in da duhovniku; in duhovnik naj izvrši poravnavo zanj z ovnom daritve za krivdo, in bo mu odpuščeno.',
        17: 'In če kdo greši in zakrivi katerokoli reč, za katero je Gospod zapovedal, da se ne sme storiti, dasi tega ni vedel, je kriv in bo nosil krivico svojo.',
        18: 'Prinese naj torej brezhibnega ovna izmed črede, po cenitvi tvoji, k duhovniku v daritev za krivdo; in duhovnik naj izvrši poravnavo zanj, za pomoto njegovo, ki jo je učinil, ne da bi bil vedel; in bo mu odpuščeno.',
        19: 'Daritev za krivdo je; kriv je bil vsekakor pred Gospodom.',
    },
    6: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'Če se kdo pregreši in zakrivi iznevero proti Gospodu s tem, da utaji bližnjemu svojemu stvar, ki mu jo je zaupal ali dal v zajem, ali mu utaji kaj ukradenega, ali če ga je opeharil,',
        3: 'ali pa je našel izgubljeno stvar in to zataji, in krivo priseže zavoljo česarkoli, kar lahko stori človek in s tem greši:',
        4: 'če se je torej pregrešil in je kriv, mora povrniti, kar je siloma vzel ali za kar je koga opeharil, ali tisto, kar mu je bilo zaupano, ali izgubljeno, kar je našel,',
        5: 'ali karkoli je, zaradi česar je krivo prisegel; povrne pa naj spolnoma in pridene še peti del; tistemu, čigar je, naj to da v dan svojega darovanja za krivdo.',
        6: 'In prinese naj k duhovniku svojo daritev za krivdo Gospodu, brezhibnega ovna izmed črede, ki je po cenitvi tvoji vreden daritve za krivdo;',
        7: 'in duhovnik naj izvrši poravnavo zanj pred Gospodom, in bode mu odpuščeno v vsem, kar kdo lahko stori, da se s tem okrivi.',
        8: 'In Gospod je govoril Mojzesu, rekoč:',
        9: 'Zapovej Aronu in sinovom njegovim takole: To je postava za žgalno daritev: Žgalna daritev bodi na ognjišču, na oltarju, vso noč do jutra; in ogenj na oltarju naj se neti, da gori na njem.',
        10: 'In duhovnik naj obleče svoje platneno oblačilo in platnene hlače naj obleče na nagoto svojo; in pospravi naj z ognjišča pepel, ki je ostal po ognju žgalne daritve na oltarju, in ga dene poleg oltarja.',
        11: 'Nato naj sleče svoja oblačila in obleče druga oblačila in naj nese pepel iz taborišča na čist kraj.',
        12: 'Ogenj pa na oltarju naj se neti, da gori, nikoli naj ne ugasne; in duhovnik naj priklada nanj drva vsako jutro in opravlja na njem žgalno daritev in sežiga na njem tolstino daritev mirovnih.',
        13: 'Ogenj naj se neti, da gori na oltarju neprenehoma, nikoli naj ne ugasne.',
        14: 'In to je postava za jedilno daritev: Sinovi Aronovi naj jo darujejo pred Gospodom, pred oltarjem.',
        15: 'Eden njih naj vzame polno prgišče bele moke in olja od jedilne daritve in vse kadilo, ki je na jedilni daritvi, in zažge naj to na oltarju v prijeten duh, v njen spomin Gospodu.',
        16: 'Kar pa je preostane, naj použije Aron in sinovi njegovi; jedlo se bo brez kvasu na svetem kraju, na dvorišču shodnega šatora naj to použijejo.',
        17: 'Ne sme se peči s kvasom. Dal sem jim to v delež pri ognjenih daritvah meni, presveto je, kakor žrtev za greh in kakor daritev za krivdo.',
        18: 'Vsak moški med otroki Aronovimi bo to jedel: večna bodi to pravica prihodnjim rodovom vašim od ognjenih daritev Gospodovih. Karkoli se jih dotakne, bo sveto.',
        19: 'In Gospod je govoril Mojzesu, rekoč:',
        20: 'To je darilo Aronovo in sinov njegovih, ki je bodo darovali Gospodu v dan, ko bo maziljen: desetino efe bele moke kot stalno jedilno daritev, polovico tega zjutraj in polovico tega zvečer.',
        21: 'V ponvi bodi pripravljena z oljem, zamešeno z oljem jo prinesi; pečeno, kot jedilno daritev v grižljajih daruj to v prijeten duh Gospodu.',
        22: 'In duhovnik, ki bo na njegovem mestu pomaziljen izmed sinov njegovih, naj to daruje; večna postava bodi: vse naj se to zažge Gospodu.',
        23: 'In vsaka jedilna daritev duhovnikova naj se vsa sežge, jesti se ne sme.',
        24: 'In Gospod je govoril Mojzesu, rekoč:',
        25: 'Govóri Aronu in sinom njegovim: To je postava daritve za greh: Na tistem kraju, kjer se koljejo žgalne daritve, naj zakoljejo daritev za greh pred Gospodom: presveta je.',
        26: 'Duhovnik, ki jo daruje za greh, jo bo jedel; na svetem kraju naj se zaužije, na dvorišču shodnega šatora.',
        27: 'Karkoli se dotakne njenega mesa, bode sveto; in če se ž njeno krvjo oškropi kako oblačilo, operi tisto, kar je bilo oškropljeno, na svetem kraju.',
        28: 'Prstena posoda pa, v kateri se je kuhala, naj se razbije; če se pa je kuhala v bronasti posodi, naj se odrgne in poplakne z vodo.',
        29: 'Vsak moški izmed duhovnikov jo bo jedel: presveta je.',
        30: 'Ali nobena daritev za greh, katere kri se prinese v shodni šator, da se v svetišču izvrši poravnava, se ne sme jesti; z ognjem naj se sežge.',
    },
    7: {
        1: 'To pa je postava daritve za krivdo: presveta je.',
        2: 'Na kraju, kjer se koljejo žgalne daritve, naj zakoljejo daritev za krivdo; in ž njeno krvjo naj duhovnik poškropi oltar kroginkrog.',
        3: 'In daruje naj vso tolstino njeno, tolsti rep in vso tolst, ki pokriva drobje,',
        4: 'in obe ledici in tolst, ki je na njiju, ki je na obledju, in pečico na jetrih, z ledicama vred naj jo odreže.',
        5: 'In duhovnik naj to zažge na oltarju kot ognjeno daritev Gospodu: daritev za krivdo je.',
        6: 'Vsak moški izmed duhovnikov jo bo jedel, na svetem kraju naj se zaužije: presveta je.',
        7: 'Kakor daritev za greh, tako daritev za krivdo: ista postava velja za obe. Duhovnik, ki izvršuje poravnavo ž njo, naj jo dobi.',
        8: 'In duhovnik, ki daruje čigarkoli žgalno daritev, naj dobi zase kožo žgalščine, ki jo je daroval.',
        9: 'In vsako jedilno daritev, ki se peče v peči, ali kar koli se pripravlja v kotlu ali v ponvi, naj dobi duhovnik, ki to daruje.',
        10: 'In vsako jedilno daritev, zamešeno z oljem ali pa suho, naj dobodo vsi sinovi Aronovi, eden kakor drugi.',
        11: 'In to je postava mirovne daritve, ki se prinaša Gospodu:',
        12: 'Če jo kdo prinese v zahvalo, naj prinese z zahvalno daritvijo vred opresne kolače, mešane z oljem, in opresne mlince, pomazane z oljem, in zamešeno belo moko, kolače, zmešane z oljem.',
        13: 'Zraven kolačev naj prinese kvašenih kruhov za darilo, s svojo zahvalno-mirovno daritvijo vred.',
        14: 'In naj daruje po en kolač od vsega darila kot podvig Gospodu; duhovnikov bodi, ki škropi kri mirovne daritve.',
        15: 'Meso pa mirovne daritve, ki je v zahvalo, naj se použije v dan njegovega darovanja; nič je ne sme ostati do jutra.',
        16: 'Ako pa je klalščina darila njegovega v izpolnitev obljube ali dobrovoljen dar, naj se použije v dan, ob katerem prinese žrtev svojo; in drugega dne se sme použiti, kar je preostane;',
        17: 'kar pa ostane mesa klalščine do tretjega dne, bodi sežgano na ognju.',
        18: 'Če pa se bo kako jedlo meso njegove mirovne daritve tretji dan, ne bo milo sprejeto, tudi ne bo veljalo za tistega, ki jo je daroval: gnusoba bode, in duša, ki zaužije od tega, bo nosila krivico svojo.',
        19: 'In meso, ki se dotakne kakršnekoli nečiste stvari, se ne sme jesti; z ognjem naj se sežge. Sicer sme jesti to meso vsak, kdorkoli je čist:',
        20: 'ali duša, ki užije meso od mirovnih daritev, lastnih Gospodu, ko je nečistota njena na njej, ta duša bo iztrebljena iz ljudstva svojega.',
        21: 'In če se kdo dotakne česa nečistega, nečistote človeka ali nečiste živali ali katerekoli nečiste gnusobe, pa zaužije meso mirovnih daritev, lastnih Gospodu, ta duša bo iztrebljena iz ljudstva svojega.',
        22: 'In Gospod je govoril Mojzesu, rekoč:',
        23: 'Govóri sinovom Izraelovim in reci: Nobene tolstine od govedi, od ovac in koz ne jejte.',
        24: 'Tolst od mrline in tolst od raztrganega živinčeta pa vsakovrstno obrnite v prid, ali je nikar ne jejte.',
        25: 'Zakaj kdorkoli jé tolstino živine, od katere se prinaša ognjena daritev Gospodu: duša, ki to užije, bo iztrebljena iz ljudstva svojega.',
        26: 'In nobene krvi ne uživajte, ne od ptic, ne od živine, po vseh prebivališčih svojih.',
        27: 'Kdorkoli bi užival kakršnokoli kri, ta duša bo iztrebljena iz ljudstva svojega.',
        28: 'In Gospod je govoril Mojzesu, rekoč:',
        29: 'Govori sinovom Izraelovim in reci: Kdor prinese mirovno daritev Gospodu, naj prinese darilo svoje Gospodu od mirovne daritve svoje.',
        30: 'V svojih rokah naj prinese, kar naj se po ognju daruje Gospodu; tolstino s prsmi vred naj prinese, da se prsi semtertja majejo v majanja dar pred Gospodom.',
        31: 'In duhovnik naj zažge tolstino na oltarju, prsi pa ostanejo Aronu in sinovom njegovim.',
        32: 'In desno stegno dajte kot dar povzdiga duhovniku od mirovnih daritev svojih.',
        33: 'Tistemu med sinovi Aronovimi, ki daruje kri mirovne daritve in tolst, bodi desno stegno v delež.',
        34: 'Zakaj prsi majalne daritve in stegno povzdiga sem vzel od sinov Izraelovih, od njih mirovnih daritev, in sem jih dal Aronu duhovniku in sinovom njegovim kot vekomaj jim določeno od sinov Izraelovih.',
        35: 'To je delež maziljenja, določen Aronu in sinovom njegovim od ognjenih daritev Gospodovih od dne, ko jim je velel pristopiti, da opravljajo duhovniško službo Gospodu;',
        36: 'o katerem je Gospod zapovedal v dan, ko jih je pomazilil, da naj ga jim dajó sinovi Izraelovi. Večna to je določba za njih prihodnje rodove.',
        37: 'To je postava žgalne in jedilne daritve in daritve za greh in za krivdo in daritve posvečevanja in mirovne daritve,',
        38: 'ki jo je Gospod ukazal Mojzesu na gori Sinajski v dan, ob katerem je zapovedal sinovom Izraelovim, da naj prinašajo darila svoja Gospodu, v puščavi Sinajski.',
    },
    8: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'Vzemi Arona in sinove njegove ž njim, in oblačila in mazilno olje in junca v daritev za greh in tista dva ovna in koš opresnikov;',
        3: 'in skliči vso občino k vhodu shodnega šatora.',
        4: 'In Mojzes stori, kakor mu je zapovedal Gospod, in občina se zbere pri vhodu shodnega šatora.',
        5: 'In Mojzes veli občini: To je, kar je zapovedal Gospod, da naj se izvrši.',
        6: 'In privede Arona in sine njegove in jih umije z vodo.',
        7: 'In njega obleče v spodnjo suknjo in ga opaše s pasom in ga odene z vrhnjo suknjo in mu nadene naramnik in ga opaše z umetno tkano prevezo naramnikovo in mu ga priveže ž njo;',
        8: 'in nanj dene naprsnik in v naprsnik dene Urim in Tumim.',
        9: 'In na glavo mu dene pokrivalo in mu na pokrivalo priveže odspredaj zlato pločo, sveti venec; kakor je bil Gospod zapovedal Mojzesu.',
        10: 'In Mojzes vzame mazilno olje in pomazili prebivališče in vse, kar je bilo v njem, in posveti vse.',
        11: 'In poškropi ž njim oltar sedemkrat, in pomazili oltar in vse priprave njegove in umivalnik in stojalo njegovo, da jih posveti.',
        12: 'In vlije mazilnega olja Aronu na glavo in ga pomazili, da ga posveti.',
        13: 'In privede Mojzes sinove Aronove in jih obleče v spodnje suknje ter jih opaše s pasovi in jim nasadi visoke čepice, kakor je bil Gospod zapovedal Mojzesu.',
        14: 'In pripelje junca v daritev za greh; Aron pa in sinovi njegovi položé roke na glavo juncu, ki je za greh.',
        15: 'In ga zakolje, in Mojzes vzame kri in jo dene s prstom na rogove oltarja kroginkrog in očisti oltar greha; in ostalo kri izlije v znožje oltarja in ga posveti, storivši poravnavo zanj.',
        16: 'In vzame vso tolstino, ki je okoli drobja, in pečico ob jetrih in obe ledici in njuno tolst, in Mojzes zažge to na oltarju.',
        17: 'Junca pa in kožo njegovo in meso in blato njegovo sežge z ognjem zunaj taborišča, kakor je bil Gospod zapovedal Mojzesu.',
        18: 'Potem pripelje ovna v žgalno daritev; Aron pa in sinovi njegovi polože roke ovnu na glavo.',
        19: 'In ga zakolje, in Mojzes razškropi kri krog po oltarju.',
        20: 'A ovna razseka na kose njegove, in Mojzes zapali glavo in kose in tolstino.',
        21: 'Drobje pa in goleni opere z vodo; in Mojzes zažge vsega ovna na oltarju: bila je žgalščina v prijeten duh, bila je ognjena daritev Gospodu, kakor je bil zapovedal Gospod Mojzesu.',
        22: 'In pripelje drugega ovna, ovna posvečenja; Aron pa in sinovi njegovi položé roke ovnu na glavo.',
        23: 'In ga zakolje, in Mojzes vzame krvi njegove ter jo dene na mečico desnega Aronovega ušesa in na palec desnice njegove in na palec desne noge njegove.',
        24: 'In veli pristopiti sinovom Aronovim, in Mojzes jim dene krvi na mečico desnega ušesa in na palec desnice in na palec desne noge; in Mojzes razškropi ostalo kri krog po oltarju.',
        25: 'In vzame tolstino in tolsti rep in vso tolstino, ki je okoli drobja, in jetrno pečico in obe ledici in njuno tolst in desno stegno;',
        26: 'in vzame iz koša opresnikov, ki je bil pred Gospodom, opresen kolač in hlebček z oljem zamešenega kruha in mlinec, in jih položi na tisto tolstino in desno stegno;',
        27: 'in dene vse to na roke Aronu in na roke sinom njegovim, da naj se to maje kot daritev majanja pred Gospodom.',
        28: 'In Mojzes vzame to spet ž njih rok in zapali to na oltarju, na žgalni daritvi: bila je daritev posvečevanja, v prijeten duh, ognjena daritev Gospodu.',
        29: 'In Mojzes vzame prsi in jih daruje z majanjem pred Gospodom: Mojzesov delež so bile od ovna posvetitve, kakor je bil Gospod zapovedal Mojzesu.',
        30: 'Mojzes vzame tudi mazilnega olja in krvi, ki je bila na oltarju, in poškropi Arona in njegova oblačila in njegove sinove in sinov njegovih oblačila ž njim vred; in posvetil je Arona, oblačila njegova, in sinove njegove in oblačila sinov njegovih ž njim vred.',
        31: 'In Mojzes veli Aronu in sinom njegovim: Kuhajte meso pri vratih shodnega šatora in ga tam zaužijte ter kruh, ki je v košu posvetitve, kakor sem zapovedal, rekoč: Aron in sinovi njegovi naj to zaužijejo.',
        32: 'Kar pa preostane mesa in kruha, sežgite z ognjem.',
        33: 'Izpred vrat shodnega šatora ne hodite sedem dni, dokler se ne dopolnijo dnevi posvečenja vašega, ker sedem dni boste posvečevani.',
        34: 'Kakor se je danes storilo, tako je zapovedal Gospod storiti, da se izvrši poravnava za vas.',
        35: 'In pri vhodu shodnega šatora ostanite po dnevi in po noči, sedem dni, in na straži bodite, izpolnjujoč povelja Gospodova, da ne umrjete; zakaj tako mi je ukazano.',
        36: 'In Aron in sinovi njegovi so storili vse, kar je bil Gospod zapovedal po Mojzesu.',
    },
    9: {
        1: 'In zgodi se osmi dan, da pokliče Mojzes Arona in sinove njegove in starejšine Izraelove,',
        2: 'ter veli Aronu: Vzemi si mlado tele v daritev za greh in ovna v žgalno daritev, brez hibe, in ju daruj pred Gospodom.',
        3: 'In sinovom Izraelovim govóri in reci: Vzemite kozla v daritev za greh in tele ter jagnje, oboje enoletno, brezhibno, v žgalno daritev;',
        4: 'in vola in ovna v mirovno daritev, da darujete pred Gospodom, in jedilno daritev, zamešeno z oljem; zakaj danes se vam prikaže Gospod.',
        5: 'Prinesli so torej, kar je ukazal Mojzes, pred shodni šator, in vsa občina je pristopila in se postavila pred Gospodom.',
        6: 'In Mojzes reče: To je, kar je zapovedal Gospod, da storite; in prikaže se vam slava Gospodova.',
        7: 'Aronu pa reče Mojzes: Pristopi k oltarju in daruj svojo daritev za greh in svojo žgalščino in izvrši poravnavo zase in za ljudstvo; daruj tudi darilo ljudstva in izvrši poravnavo zanje, kakor je bil zapovedal Gospod.',
        8: 'In Aron pristopi k oltarju in zakolje tele daritve za greh, ki je bila za njega.',
        9: 'In sinovi Aronovi mu podado kri; in si omoči prst v krvi in jo dene na rogove oltarja, in ostalo kri izlije v znožje oltarja.',
        10: 'Tolstino pa in ledici in jetrno pečico od daritve za greh zapali na oltarju; kakor je bil Gospod zapovedal Mojzesu.',
        11: 'A meso in kožo sežge z ognjem zunaj šatorišča.',
        12: 'In zakolje žgalno žrtev; in sinovi Aronovi mu izročé kri, in razškropi jo krog po oltarju.',
        13: 'Žgalno žrtev pa mu prineso po njenih kosih in glavo, in zažge jo na oltarju.',
        14: 'In opere drob in noge in zažge to vrhu žgalne daritve na oltarju.',
        15: 'In prinese darilo ljudstva, in vzame kozla daritve za greh, ki je bila za ljudstvo, in ga zakolje in daruje za greh kakor ono prvo.',
        16: 'In prinese žgalno daritev in jo daruje po predpisu.',
        17: 'In prinese jedilno daritev in je vzame polno prgišče, in zažge to na oltarju zraven zjutranje žgalne daritve.',
        18: 'In zakolje vola in ovna, mirovno daritev, ki je bila za ljudstvo. Sinovi Aronovi pa mu podajajo kri, ki jo razškropi krog po oltarju,',
        19: 'in tolstino vola in ovnov tolsti rep in kar pokriva drob in ledici ter jetrno pečico,',
        20: 'in polože tolstino na prsne kose, in zažge tolstino na oltarju.',
        21: 'A prsne kose in desno stegno daruje Aron z majanjem pred Gospodom, kakor je zapovedal Mojzes.',
        22: 'Potem povzdigne Aron roko proti ljudstvu in ga blagoslovi; in ko opravi daritev za greh in žgalno in mirovno daritev, stopi doli od oltarja.',
        23: 'Nato gresta Mojzes in Aron v shodni šator; in ko prideta ven, blagoslovita ljudstvo: in prikaže se slava Gospodova vsemu ljudstvu.',
        24: 'In ogenj pride izpred Gospoda in požre na oltarju žgalno daritev in tolstino; in vse ljudstvo, videč to, zauka veselo in popada na obličje svoje.',
    },
    10: {
        1: 'Aronova sinova pa, Nadab in Abihu, vzameta vsak kadilnico svojo in deneta ognja vanjo in položita nanj kadila, in prineseta tuj ogenj pred Gospoda, česar jim ni bil zapovedal.',
        2: 'Zato pride ogenj izpred Gospoda in ju usmrti, in umrla sta pred Gospodom.',
        3: 'Tedaj reče Mojzes Aronu: To je, kar je govoril Gospod, rekoč: Posvečen bom v njih, ki se mi bližajo, in pred obličjem vsega ljudstva se oslavim. Aron pa molči.',
        4: 'In Mojzes pokliče Misaela in Elzafana, sinova Uziela, strica Aronovega, in jima veli: Pristopita, odnesita brata svoja iz svetišča ven za taborišče.',
        5: 'Stopita torej noter in ju odneseta v njunih suknjah ven za taborišče, kakor je rekel Mojzes.',
        6: 'In Mojzes reče Aronu in Eleazarju in Itamarju, njegovima sinoma: Ne odkrivajte si glav in oblačil svojih ne trgajte, da ne umrjete ter da se On ne razjezi nad vso občino Izraelovo; ampak bratje vaši, vsa Izraelova hiša naj plačejo zaradi tega požara, ki ga je napravil Gospod.',
        7: 'In iz vrat shodnega šatora ne odhajajte, da ne umrjete, zakaj olje maziljenja Gospodovega je na vas. In storili so po besedi Mojzesovi.',
        8: 'In Gospod je govoril Aronu, rekoč:',
        9: 'Vina in opojne pijače ne pij, ne ti, ne sinovi tvoji s teboj, kadar vhajate v shodni šator, da ne umrjete. Večna bodi to postava po rodovih vaših,',
        10: 'da morete razpoznati, kaj je sveto in kaj nesveto, kaj je čisto in kaj nečisto,',
        11: 'in da učite sinove Izraelove vse postave, katere jim je govoril Gospod po Mojzesu.',
        12: 'In Mojzes ogovori Arona in Eleazarja in Itamarja, sinova njegova, ki sta ostala: Vzemite jedilno daritev, ki je ostala od ognjenih daritev Gospodovih, in uživajte jo z opresniki pri oltarju, kajti presveta je.',
        13: 'Zato jo uživajte na svetem kraju, zakaj določena je tebi in določena je sinovom tvojim od ognjenih daritev Gospodovih; kajti tako mi je ukazano.',
        14: 'Prsi majanja pa in stegno podviga jejte na čistem kraju, ti in sinovi tvoji in hčere tvoje s teboj; zakaj kot tebi določeno in otrokom tvojim določeno je dano to od mirovnih daritev sinov Izraelovih.',
        15: 'Stegno podviga in prsi majanja naj prineso z ognjenimi žrtvami tolstine vred, da se darujejo z majanjem pred Gospodom: in tvoje bodi to in sinov tvojih s teboj kot tebi določeno vekomaj, kakor je Gospod zapovedal.',
        16: 'Mojzes pa se skrbno ozira, kje je kozlič v daritev za greh, in glej, sežgan je bil. In razsrdi se nad Eleazarjem in Itamarjem, Aronovima sinoma, ki sta ostala živa, in reče:',
        17: 'Zakaj nista zaužila daritve za greh na svetem kraju? saj je presveta, in On vama jo je dal, da bi nosila krivico občine, da storita poravnavo zanje pred Gospodom.',
        18: 'Glejta, njena kri se ni ponesla v svetišče: morala bi jo bila torej použiti na svetem kraju, kakor sem bil zapovedal.',
        19: 'Aron pa odgovori Mojzesu: Glej, danes sta darovala svojo daritev za greh in svojo žgalno daritev pred Gospodom, in mene je zadela taka reč; če bi bil jedel daritev za greh danes, ali bi bilo dobro v očeh Gospodovih?',
        20: 'Ko Mojzes to sliši, se mu prav vidi.',
    },
    11: {
        1: 'In Gospod je govoril Mojzesu in Aronu, rekoč jima:',
        2: 'Govorita sinovom Izraelovim in recita: To so živali, ki jih smete jesti izmed vse živadi, ki je na zemlji.',
        3: 'Vse, kar dvoji parklje, in sicer kar ima ves parkelj razdeljen, in prežvekuje, izmed četveronožcev, smete jesti.',
        4: 'Samo teh ne smete jesti izmed tistih, ki prežvekujejo, in izmed tistih, ki dvojé parkelj: velbloda, ki prežvekuje, pa nima razdvojenega parklja: nečist vam bodi;',
        5: 'in skalnega jazbeca, ki prežvekuje, a nima razdvojenega parklja: nečist vam bodi;',
        6: 'in zajca, ki prežvekuje, a ne dvoji parklja: nečist vam bodi;',
        7: 'in svinje, ki pač dvoji parklje in to popolnoma, pa ne prežvekuje: nečista vam bodi.',
        8: 'Njih mesa ne jejte in njih mrtvih trupel se ne dotikajte, nečiste naj vam bodo.',
        9: 'Tele pa smete jesti od vseh, ki žive v vodah: karkoli ima plavute in luske v vodah, v morjih in rekah, smete jesti.',
        10: 'Karkoli pa nima plavut in lusk v morjih in rekah, izmed vsega, kar se giblje po vodah in kar živi v vodi, bodi vam gnusoba.',
        11: 'Gnusne naj vam bodo: njih mesa ne jejte in njih mrline naj se vam studijo.',
        12: 'Vse, kar nima plavut in lusk v vodah, bodi vam gnusoba.',
        13: 'In te naj vam bodo mrzke med pticami, ne jejte jih, gnusoba so: orel in brkati ser in morski orel,',
        14: 'in sokol in kanja po svojih plemenih,',
        15: 'in vsak gavran po svojih plemenih,',
        16: 'in noj in kukavica in morski galeb in jastreb po svojih plemenih,',
        17: 'in skovir in potapljač in vir,',
        18: 'in sova in pelikan in mrhar,',
        19: 'in štorklja in čaplja po svojih plemenih, smrdokavra in netopir.',
        20: 'Vsa okriljena živad, ki hodi po štirih nogah, vam bodi gnusoba.',
        21: 'Samo to smete jesti izmed vse krilate živadi, ki hodi po štirih: kar ima stegna na zgornjem delu nog, da ž njimi skače po zemlji.',
        22: 'Te smete jesti izmed nje: arbo po njenih plemenih, solhamo po njenih plemenih, hargolo po njenih plemenih in hagabo po njenih plemenih.',
        23: 'Toda vsa druga krilata živad, ki ima štiri noge, vam bodi gnusoba.',
        24: 'In s temi se boste onečistili; kdorkoli se dotakne njih mrhovine, bode nečist do večera;',
        25: 'in kdor koli ponese kaj njih mrhovine, naj si izpere oblačila, in nečist bodi do večera.',
        26: 'Vsaka žival, ki dvoji parklje, pa jih nima docela razdeljenih, tudi ne prežvekuje, vam bodi nečista: vsak, kdor se je dotakne, bode nečist.',
        27: 'In vse, kar hodi po svojih šapah med vso zverjadjo, ki hodi po štirih, vam bodi nečisto: kdorkoli se dotakne njih mrhovine, bode nečist do večera.',
        28: 'In kdor bi nosil njih mrhovino, naj si izpere oblačila, in bode nečist do večera; nečiste naj vam bodo.',
        29: 'In te naj vam bodo nečiste med živalmi, ki lazijo po zemlji: podlasica, miš in kuščarica po svojih plemenih,',
        30: 'in anaka in koah in letaa in komet in kameleon.',
        31: 'Te naj vam bodo nečiste med vso laznino: kdorkoli se jih dotakne, ko so mrtve, bode nečist do večera.',
        32: 'In na karkoli pade katerekoli izmed njih mrlina, bode nečisto: vsaka lesena posoda ali oblačilo ali koža ali vreča, kakršnosibodi orodje, s katerim se kaj dela, se mora deti v vodo, in nečisto bode do večera; potem bode čisto.',
        33: 'In vsaka prstena posoda, v katero pade ena izmed njih: vse kar je v njej, bode nečisto, in posoda naj se razbije.',
        34: 'Vsaka jed, ki se jé, ako vanjo pride taka voda, bode nečista; in vsaka pijača, ki se pije, bode nečista v vsaki taki posodi.',
        35: 'In vse, na kar pade kaj njih mrline, bode nečisto; peč in ognjišče naj se zrušita, nečisto je, in nečisto vam bodi.',
        36: 'Toda studenci in vodnjaki, kjer se steka voda, bodo čisti; ako se pa kdo dotakne mrhovine v njih, bode nečist.',
        37: 'In če kaj njih mrhovine pade na seme, ki je za setev, ostane čisto;',
        38: 'ako se pa voda izlije na seme in pade kaj njih mrhovine nanje, nečisto vam bode.',
        39: 'In če pogine ena izmed živali, ki so vam v živež: kdor se dotakne mrline njene, nečist bode do večera.',
        40: 'In ako bi kdo jedel od mrline njene, naj si izpere oblačila, in bode nečist do večera; in kdor ponese mrhovino njeno, naj si izpere oblačila, in bode nečist do večera.',
        41: 'In sleherna laznina, ki lazi po zemlji, je gnusoba; ne smete je jesti.',
        42: 'Vse, kar se plazi po trebuhu, in vse, kar hodi po štirih, in karkoli je mnogonožno med vso laznino, ki se giblje po zemlji: ne smete tega jesti, zakaj mrzko je.',
        43: 'Ne ognušajte sami sebe s katero koli lazečo črvadjo in ne onečiščajte se ž njimi, da bi se s tem omadeževali.',
        44: 'Zakaj jaz sem Gospod, Bog vaš, zato se posvečujte in bodite sveti, ker jaz sem svet. Ne oskrunite torej sami sebe s katerokoli črvadjo, ki se giblje na zemlji.',
        45: 'Zakaj jaz sem Gospod, ki sem vas pripeljal iz dežele Egiptovske, da vam bodem Bog: sveti torej bodite, ker jaz sem svet.',
        46: 'To je postava zastran živali in letečine in zastran vsake žive stvari, ki se giblje po vodah, in vsake golazni, ki lazi po zemlji;',
        47: 'da ločite med nečistim in čistim, med živalmi, ki se uživajo, in živalmi, ki se ne smejo jesti.',
    },
    12: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'Govóri sinovom Izraelovim in reci: Če žena spočne in porodi moško dete, nečista bodi sedem dni; nečista bode kakor v dnevih ločitve v bolezni svoji.',
        3: 'In osmi dan naj se obreže meso kožice njegove.',
        4: 'Ona pa naj še ostane triintrideset dni v krvi svojega očiščevanja; ničesar svetega naj se ne dotakne in k svetišču naj ne hodi, dokler se ne dopolnijo dnevi očiščevanja njenega.',
        5: 'Ako pa rodi žensko dete, bodi nečista dva tedna, kakor ob mesečni ločitvi svoji; in šestinšestdeset dni naj še ostane v krvi očiščevanja.',
        6: 'Ko pa se dopolnijo dnevi očiščevanja njenega za sina ali za hčer, naj prinese enoletno jagnje v žgalno daritev ali golobiča ali grlico v daritev za greh duhovniku pred vrata shodnega šatora.',
        7: 'Ta pa naj to daruje pred Gospodom in izvrši poravnavo zanjo, in čista bode toka krvi svoje. To je postava roditeljicam pri moškem ali ženskem detetu.',
        8: 'Ako pa imetje njeno ni zadostno za ovco, naj vzame dve grlici ali dva golobiča, enega v žgalščino in drugega v daritev za greh; in duhovnik naj stori poravnavo zanjo, in čista bode.',
    },
    13: {
        1: 'In Gospod je govoril Mojzesu in Aronu, rekoč:',
        2: 'Če dobi človek na koži mesa svojega izpuščaj ali krasto ali svetlo pego, kakor da bi bilo na koži mesa njegovega znamenje gob, naj ga privedejo k Aronu, duhovniku, ali h kateremu sinov njegovih, duhovnikov.',
        3: 'Duhovnik pa ogleda boleznivo reč na koži mesa njegovega: ako se je kosmatina na boleznivem kraju pobelila in boleznivina se vidi globokejša nego koža mesa njegovega, gobava bolezen je; duhovnik ga torej pregleda in ga proglasi za nečistega.',
        4: 'Ako pa je bela pega na koži mesa njegovega, pa se ne vidi globokejša nego koža in tudi kosmatina na njem se ni pobelila, naj zapre duhovnik za tako boleznijo bolnega sedem dni.',
        5: 'In sedmi dan ga ogleda duhovnik, in glej, znamenje bolezni, kakor mu kažejo oči, je ostalo, a se ni razširilo po koži: tedaj ga duhovnik zapre sedem dni v drugič.',
        6: 'In sedmi dan naj ga ogleda duhovnik zopet, in glej, boleznivo znamenje je otemnelo in se ni razširilo po koži: duhovnik ga torej proglasi za čistega; krasta je, in opere naj si oblačila, in bode čist.',
        7: 'Ako pa se razširi krasta po koži, potem ko se je pokazal duhovniku v očiščenje, naj se drugič pokaže duhovniku;',
        8: 'in duhovnik ga ogleda, in glej, krasta se je res razširila po koži: tedaj ga duhovnik proglasi za nečistega; gobe so.',
        9: 'Ko je znamenje gob na človeku, naj ga privedejo k duhovniku.',
        10: 'In duhovnik ga ogleda, in glej, na koži ima bel izrinek, od katerega se je kosmatina pobelila, in hudo meso je zraslo na izrinku:',
        11: 'stare gobe so v koži njegovega mesa, zato naj ga duhovnik proglasi za nečistega; ne zapre naj ga, ker je nečist.',
        12: 'Ako pa se gobe izrinejo na koži in pokrijejo vso kožo bolnikovo od glave do nog njegovih, kamor koli pogleda duhovnik;',
        13: 'in duhovnik ga ogleda, in glej, gobe pokrivajo vse telo njegovo: tedaj naj proglasi bolnika za čistega; če se je povsem premenilo v belo, je čist.',
        14: 'Kadarkoli pa se prikaže hudo meso na njem, bode nečist.',
        15: 'In zagleda li duhovnik hudo meso, naj ga proglasi za nečistega; hudo meso je nečisto, gobe so.',
        16: 'Če se pa hudo meso premeni in izprevrne v belo, naj pride k duhovniku;',
        17: 'in duhovnik ga ogleda, in glej, znamenje bolezni se je izprevrnilo v belo: tedaj naj proglasi duhovnik njega, ki ima to nadlogo, za čistega; čist je.',
        18: 'In če se naredi ulje na mesu, na njegovi koži, pa se zaceli,',
        19: 'in na mestu uljesa je bel izrinek ali svetlordeča pega: naj se pokaže duhovniku;',
        20: 'in duhovnik ga ogleda, in glej, vidi se to globočje nego koža in kosmatina se je ondi pobelila: tedaj naj ga duhovnik proglasi za nečistega; bolezen gob je, v uljesu so nastale.',
        21: 'Ali če ga duhovnik ogleda, in glej, ni bele kosmatine na njem in ni globočje od kože, a je otemnelo, naj ga zapre duhovnik sedem dni;',
        22: 'in ako se razširi po koži, naj ga duhovnik proglasi za nečistega; bolezen je.',
        23: 'Ako pa ostane pega na svojem mestu in se ne razraste: brazgotina je po uljesu, in duhovnik naj ga proglasi za čistega.',
        24: 'Ali pa če je spečenina na mesu, na koži njegovi, in na hudem mesu spečenine se naredi svetlordeča ali bela pega;',
        25: 'in duhovnik ga ogleda, in glej, kosmatina se je pobelila na pegi in pega se vidi globočja nego koža: gobe so, v spečenini so se izpustile; duhovnik naj ga torej proglasi za nečistega; gobavost je.',
        26: 'Če ga pa duhovnik ogleda, in glej, nobene bele kosmatine ni ob pegi ter nižja ni nego koža in je otemnela: naj ga duhovnik zapre sedem dni.',
        27: 'In sedmi dan naj ga ogleda duhovnik; ako se je pega razširila po koži, naj ga duhovnik proglasi za nečistega; gobavost je.',
        28: 'Če pa je pega ostala na svojem mestu in se ni razširila po koži, a je temna: izrinek je spečenine, in duhovnik naj ga proglasi za čistega, kajti brazgotina je po spečenini.',
        29: 'In ako dobi mož ali žena boleznivo znamenje na glavi ali na bradi,',
        30: 'naj ogleda duhovnik boleznivino: in glej, kaže se globočja od kože in je na njej žolta, tenka kosmatina, naj ga torej duhovnik proglasi za nečistega: krastovina je, gobe so na glavi ali na bradi.',
        31: 'Če pa duhovnik pregleda krastavo znamenje, in glej, ne kaže se globočje od kože, tudi ni črne kosmatine na njem: zapre naj ga duhovnik krastavega sedem dni.',
        32: 'In ko ogleda duhovnik bolezen sedmi dan, in glej, kraste se niso dalje razrasle in ni žolte kosmatine na njih in krastovina se ne kaže globočja nego koža,',
        33: 'naj se človek obrije, pa krastovine ne obrije; in duhovnik naj zapre krastavega sedem dni drugič.',
        34: 'In sedmi dan ogleda duhovnik kraste in razvidi, da se krastovina ni razširila po koži in se ne kaže globočja od kože: tedaj naj ga duhovnik proglasi za čistega, in opere naj si oblačila, in bode čist.',
        35: 'Ako se pa krastovina razširi po koži, potem ko je bil za čistega proglašen,',
        36: 'in duhovnik ga pregleda, in glej, krastovina se je razrasla po koži, ne ozira naj se po žolti kosmatini: nečist je.',
        37: 'Ako pa se je, kakor mu oči kažejo, krastovina ustavila in zrasla na njej črna kosmatina, so se zacelile kraste: čist je, in duhovnik naj ga proglasi za čistega.',
        38: 'In če dobi mož ali žena maroge po koži mesa svojega, belognojne maroge,',
        39: 'in duhovnik jih pregleda, in glej, po koži njih mesa so blede, belognojne maroge: izpuščaj je, ki se je izrinil na kožo; človek je čist.',
        40: 'Ako možu lasje gredo z glave, je plešec, pa je čist;',
        41: 'tudi če mu lasje opolznejo s prednje strani temena, je spredaj plešast, pa je čist.',
        42: 'Ako pa je na prednji ali na zadnji plešini belordečkasto znamenje, so gobe, ki so se izpehnile na prednji ali na zadnji plešini njegovi.',
        43: 'In duhovnik ga ogleda, in glej, izrastek boleznivega znamenja je belordečkast na njegovi prednji ali zadnji pleši in se vidi kakor gobe na koži mesa,',
        44: 'tedaj je mož gobavec: nečist je, in duhovnik naj ga odločno proglasi za nečistega; bolezen svojo ima na glavi.',
        45: 'Zastran gobavca pa, ki ima bolezen: oblačila naj ima natrgana in glavo razkrito in ustnice naj si pokriva ter vpije: Nečist, nečist!',
        46: 'Vse dni, dokler ima bolezen, naj ga štejejo za nečistega; nečist je, sam naj prebiva, zunaj šatorišča bodi njegov stan.',
        47: 'In če se pojavi znamenje gob na obleki, bodisi volnata ali platnena obleka,',
        48: 'naj bo na osnutku ali na votku, platnenem ali volnatem, ali na koži, ali na kakršnikoli kožuhovini:',
        49: 'če je znamenje zelenkasto ali rdečkasto na obleki ali na koži, ali na osnutku ali na votku, ali na kakršnikoli pripravi iz kože, tedaj je znamenje gob, in naj se pokaže duhovniku.',
        50: 'In duhovnik naj ogleda znamenje in zapre tisto, na čemer je znamenje, sedem dni.',
        51: 'In če zazna sedmi dan, da se je znamenje razširilo po obleki, ali po osnutku ali po votku, ali po koži, pri čemerkoli se rabi koža: znamenje to so razjedljive gobe; nečisto je.',
        52: 'Sežge naj se torej obleka, ali osnutek ali votek, volnat ali platnen, ali katerakoli priprava iz kože, ki je na njej znamenje to; zakaj razjedljive gobe so: mora se sežgati z ognjem.',
        53: 'Ako pa to duhovnik pregleda, in glej, znamenje se ni razširilo po obleki, ali po osnutku ali po votku, ali na kakršnikoli pripravi iz kože,',
        54: 'naj zapove, da se opere tisto, na čemer je tako znamenje; potem naj zapre to sedem dni drugič.',
        55: 'In duhovnik ogleda znamenje, potem ko se je opralo, in glej, znamenje ni premenilo svoje podobe, čeprav se ni razširilo: nečisto je, z ognjem naj se sežge; razjedljiva stvar je na robu ali na licu.',
        56: 'In če to duhovnik ogleda, in glej, znamenje je obledelo po pranju, naj je odtrga od obleke, ali od kože, ali od osnutka ali od votka.',
        57: 'Ako se pa bo še videlo na obleki, ali na osnutku ali na votku, ali na čemerkoli iz kože: gobe so, ki se vnovič izpuščajo; z ognjem sežgi, na čemer je znamenje to.',
        58: 'Obleka pa, ali osnutek ali votek, ali katerakoli priprava iz kože, ki jo izpereš, in znamenje izgine: drugič se mora oprati, in potem je čista.',
        59: 'To je postava zastran znamenja gob na obleki, volnati ali platneni, ali na osnutku ali na votku, ali na katerikoli pripravi iz kože, kako naj se proglasi za čisto ali nečisto.',
    },
    14: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'To bodi postava gobavcu na dan očiščenja njegovega: Pripeljejo naj ga k duhovniku;',
        3: 'duhovnik pa naj pride ven iz šatorišča in ga ogleda, in glej, boleznivo znamenje gob je zaceljeno na gobavcu:',
        4: 'ukaži torej duhovnik, da naj vzamejo za njega, ki ima biti očiščen, dve živi, čisti ptici in cedrovega lesa in karmezina in izopa.',
        5: 'In ukaži duhovnik, naj zakoljejo eno teh ptic v prsteno posodo nad tekočo vodo.',
        6: 'Živo ptico pa vzame in cedrovino in karmezin in izop in omoči vse v krvi nad živo vodo zaklane ptice,',
        7: 'in poškropi naj sedemkrat njega, ki želi biti očiščen gob, in ga proglasi za čistega; potem spusti živo ptico, da zleti na plano.',
        8: 'Tisti pa, ki se očiščuje, naj si opere oblačila in si obrije vso kosmatino in se izkoplje v vodi, in je čist. In potem sme priti v šatorišče, ostane pa naj zunaj šatora svojega sedem dni.',
        9: 'In sedmi dan naj si obrije vso kosmatino, glavo ter brado in obrvi; da, vse lase naj si obrije in opere oblačila in telo si izkoplje v vodi; in je čist.',
        10: 'Osmi dan pa naj vzame dve jagnjeti, brez madeža, in ovco enoletno, brez hibe, in tri desetinke bele moke v jedilno daritev, pomešane z oljem, in log olja.',
        11: 'Duhovnik pa, ki ga očiščuje, naj postavi moža, ki ima biti očiščen, z vsem tem pred Gospoda, pri vratih shodnega šatora.',
        12: 'In duhovnik vzemi eno jagnje in ga daruj v daritev za krivdo in log olja, in majaj oboje kot daritev majanja pred Gospodom;',
        13: 'in zakolje naj jagnje na kraju, kjer se koljejo daritve za greh in žgalščine, na svetem kraju; zakaj kakor daritev za greh je duhovniku odmenjena tudi daritev za krivdo: presveta je.',
        14: 'In vzame naj duhovnik krvi daritve za krivdo ter jo deni na desno ušesno mečico očiščevanca in na desni palec roke in na desni palec noge njegove.',
        15: 'In vzame naj duhovnik nekoliko od loga olja in si ga vlije na levo roko,',
        16: 'in omoči naj desni prst svoj v olju, ki je na levi dlani njegovi, in s prstom naj škropi olje sedemkrat pred Gospodom.',
        17: 'Od ostanka olja pa, ki je na dlani njegovi, naj dene duhovnik na desno ušesno mečico očiščevanca in na desni palec roke in na desni palec noge njegove, vrh krvi daritve za krivdo.',
        18: 'Ostanek olja pa, ki je na roki duhovnikovi, naj dene očiščevancu na glavo; in tako naj izvrši duhovnik poravnavo zanj pred Gospodom.',
        19: 'In naj opravi duhovnik daritev za greh in stori poravnavo za očiščevanca zaradi nečistote njegove, in potem naj zakolje žgalno daritev.',
        20: 'Žgalno pa in jedilno daritev naj daruje duhovnik na oltarju ter izvrši poravnavo zanj, in bode čist.',
        21: 'Ako je pa ubožen in toliko ne premore, naj vzame eno jagnje v dar za krivdo, v daritev majanja, da se stori poravnava zanj, in desetinko bele moke, oblite z oljem, v jedilno daritev, in log olja',
        22: 'in dve grlici ali dva golobiča, kakršna si lahko priskrbi, in eden bodi v daritev za greh in drugi v žgalno daritev.',
        23: 'In naj to prinese osmi dan po očiščenju svojem k duhovniku, k vratom shodnega šatora, pred Gospoda.',
        24: 'Duhovnik pa vzemi jagnje, ki je v daritev za krivdo, in log olja, in daruj oboje kot daritev majanja pred Gospodom.',
        25: 'In zakolje naj jagnje v daritev za krivdo in vzame krvi daritve za krivdo ter jo deni na desno ušesno mečico očiščevanca in na desni palec roke in na desni palec noge njegove.',
        26: 'Od olja pa naj si vlije duhovnik na levo roko;',
        27: 'in z desnim prstom svojim naj poškropi duhovnik olja, ki je na levi roki njegovi, sedemkrat pred Gospodom.',
        28: 'In naj dene duhovnik olja, ki ga ima na dlani, na desno ušesno mečico očiščevancu in na desni palec roke in na desni palec noge njegove, tja, kjer je kri daritve za krivdo.',
        29: 'Ostanek olja pa, ki je na dlani duhovnikovi, naj dene očiščevancu na glavo, da stori poravnavo zanj pred Gospodom.',
        30: 'In naj daruje eno izmed grlic ali golobičev, kakršna si lahko priskrbi,',
        31: 'taka, kakršna priskrbi, enega za greh in drugega v žgalno daritev, z jedilno daritvijo vred, in tako naj stori duhovnik poravnavo za očiščevanca pred Gospodom.',
        32: 'To je postava za njega, ki je gobav, čigar imetje ni zadostno pri očiščevanju njegovem.',
        33: 'In Gospod je govoril Mojzesu in Aronu, rekoč:',
        34: 'Ko pridete v deželo Kanaansko, ki vam jo jaz dam v posest, pa pošljem nadlogo gob nad katero hišo v deželi lastnine vaše,',
        35: 'tedaj naj pride tisti, čigar je hiša, in naznani duhovniku, rekoč: Kaže se mi, kakor da bi bilo znamenje gob na hiši.',
        36: 'Nato zapove duhovnik, da naj izpraznijo hišo, preden pride ogledovat znamenje, da bi ne postalo nečisto vse, kar je v hiši; in potem naj vstopi duhovnik, da ogleda hišo.',
        37: 'In ko pogleda znamenje, in glej, znamenje je na hišnih stenah, zelenkaste ali rdečkaste jamice, ki so se zajedle globoko v steno:',
        38: 'tedaj naj gre duhovnik ven iz hiše k hišnim vratom in zapre hišo za sedem dni.',
        39: 'In ko pride zopet osmi dan in pogleda, in glej, znamenje se je razlezlo po steni:',
        40: 'tedaj zapovej duhovnik, naj izdero kamene, na katerih je tisto znamenje, in jih pomečejo za mesto na nečist kraj.',
        41: 'Hišo pa naj odznotraj vso ostrgajo in ostržke izsujejo za mesto na nečist kraj.',
        42: 'In druge kamene naj vzamejo in jih denejo namesto onih kamenov, in z drugim ilom naj omažejo hišo.',
        43: 'Ako se pa znamenje zopet pojavi in se izrine po hiši, potem ko so izdrli one kamene in potem ko so hišo ostrgali in omazali,',
        44: 'in duhovnik pride in vidi, da se je znamenje razširilo po hiši: razjedljive gobe so na hiši, nečista je.',
        45: 'Razrušijo naj hišo, kamene in les in ves omaz njen, in vse naj spravijo ven za mesto na nečist kraj.',
        46: 'In kdor bo vstopil v hišo, dokler bo zaprta, nečist bodi do večera.',
        47: 'In kdor bi spal v hiši, naj si izpere oblačila, in kdor bi jedel v hiši, naj si opere oblačila.',
        48: 'Ko pa pride duhovnik in pogleda, in glej, znamenje se ni razširilo po hiši, potem ko so jo vnovič omazali: naj proglasi hišo za čisto, kajti znamenje se je izcelilo.',
        49: 'In vzame naj, da očisti hišo greha, dve ptici in cedrovega lesa in karmezina in izopa.',
        50: 'In zakolji eno ptico v prsteno posodo nad tekočo vodo;',
        51: 'in vzemi cedrovino in izop in karmezin in živo ptico, in omóči vse v krvi zaklane ptice in v tekoči vodi, in poškrópi hišo sedemkrat;',
        52: 'in tako naj hišo očisti greha s krvjo ptice in s tekočo vodo in z živo ptico in s cedrovino in z izopom in s karmezinom,',
        53: 'nato spústi živo ptico, da zleti ven iz mesta na plano. Tako naj izvrši poravnavo za hišo, in čista bode.',
        54: 'To je postava za vsakršno gobavo nadlogo in za garje',
        55: 'in za gobe na obleki in na hiši',
        56: 'in za izpuščaj in za kraste in za svetle pege:',
        57: 'v poučilo, kdaj je kaj nečisto in kdaj je kaj čisto. To je postava o gobah.',
    },
    15: {
        1: 'In Gospod je govoril Mojzesu in Aronu, rekoč:',
        2: 'Govorita sinovom Izraelovim in jim recita: Če ima mož sluzotok iz mesa svojega, nečist je zaradi toka svojega.',
        3: 'In to bodi nečistost njegova pri toku njegovem: pušča li meso njegovo tok, da se cedi, ali pa se zapre meso njegovo pred tokom, v nečistost si štej to.',
        4: 'Vsako ležišče, na katerem leži, kdor ima tok, bodi nečisto, in na čimerkoli sedi, bodi nečisto.',
        5: 'In kdor se dotakne ležišča njegovega, naj si opere oblačila in se izkoplje v vodi, in bodi nečist do večera.',
        6: 'In kdor sede, kjer je sedel on, ki ima tok, naj si opere oblačila in se izkoplje v vodi, in bodi nečist do večera.',
        7: 'In kdor se dotakne mesa tistega, ki ima tok, naj si opere oblačila in se izkoplje v vodi, in bodi nečist do večera.',
        8: 'In če tisti, ki ima tok, pljune na čistega, ta naj si opere oblačila in se izkoplje v vodi, in nečist bodi do večera.',
        9: 'Tudi vsako sedlo, na katerem jezdi, kdor ima tok, bode nečisto.',
        10: 'In kdor koli se dotakne česa, kar je bilo pod njim, nečist bode do večera; in kdor nese tisto, naj si opere oblačila in se izkoplje v vodi, in nečist bodi do večera.',
        11: 'Vsakdo, ki se ga dotakne tisti, ki ima tok, ne da bi si prej roke umil, naj opere oblačila svoja in se izkoplje v vodi, in nečist bodi do večera.',
        12: 'Vsaka prstena posoda, ki se je dotakne tisti, ki ima tok, naj se razbije, lesena pa naj se pomije z vodo.',
        13: 'Kadar pa bode tisti, ki ima tok, čist svojega toka, naj šteje sedem dni od svoje očistitve in si opere oblačila in izkoplje meso svoje v tekoči vodi, in bode čist.',
        14: 'Osmi dan pa naj si vzame dve grlici ali dva golobiča in pride pred Gospoda k vratom shodnega šatora in ju izroči duhovniku.',
        15: 'In duhovnik ju daruj, eno v daritev za greh in eno v žgalno daritev, in stóri poravnavo zanj pred Gospodom zaradi toka njegovega.',
        16: 'In če možu uide seme združenja, naj si izkoplje vse telo v vodi, in bodi nečist do večera.',
        17: 'In vsaka obleka in vsaka koža, na katero pride seme združenja, naj se opere z vodo, in nečista bodi do večera.',
        18: 'In če bo z ženo ležal mož z iztokom semena, naj se izkopljeta v vodi, in bodeta nečista do večera.',
        19: 'In ko ima žena tok, in njen tok na mesu njenem je kri, naj bode sedem dni ločena; in kdorkoli se je dotakne, bode nečist do večera.',
        20: 'In vse, na čemer leži ob ločitvi svoji, bode nečisto, in na čemerkoli sedi, bo nečisto.',
        21: 'In vsak, ki se dotakne ležišča njenega, naj si opere oblačila in se izkoplje v vodi, in nečist bode do večera.',
        22: 'In kdor koli se dotakne česa, na čemer je sedela, naj si opere oblačila in se izkoplje v vodi, in bode nečist do večera.',
        23: 'In če je kaj na ležišču ali na opravi, na kateri je sedela, kdor se tega dotakne, bode nečist do večera.',
        24: 'In ako bi mož ležal ž njo in nečistota njena pride nanj, nečist bode sedem dni; in vsako ležišče, na katerem leži, bode nečisto.',
        25: 'In ako ima žena krvotok mnogo dni zunaj časa ločitve svoje, ali če ima tok čez čas ločitve svoje: kolikorkoli dni traja tok nečistote njene, naj bode kakor v dnevih ločitve svoje: nečista je.',
        26: 'Vsako ležišče, na katerem leži v dnevih toka svojega, naj ji bode kakor ležišče ločitve njene, in vsaka oprava, na kateri sedi, bodi nečista kakor nečistota ločitve njene.',
        27: 'In kdorkoli se teh reči dotakne, bode nečist, in naj si opere oblačila in se izkoplje v vodi, in nečist bodi do večera.',
        28: 'In kadar bode čista toka svojega, naj si šteje sedem dni, in potem bodi čista.',
        29: 'In osmi dan naj vzame zase dve grlici ali dva golobiča in ju prinese duhovniku k vratom shodnega šatora.',
        30: 'In duhovnik daruj eno v daritev za greh, drugo pa v žgalno daritev. In tako naj stori duhovnik poravnavo zanjo pred Gospodom zaradi toka nečistosti njene.',
        31: 'Tako učite sinove Izraelove, da se ločijo od nečistosti svoje, da ne umrjo v nečistosti svoji, oskrunivši šator moj, ki je sredi njih.',
        32: 'To je postava za tistega, ki ima tok in ki mu seme uhaja, da se onečisti s tem,',
        33: 'in za tisto, ki je bolna ob ločitvi, in za tiste, ki imajo tok, bodisi mož ali žena, in za moža, ki leži z nečisto.',
    },
    16: {
        1: 'In Gospod je govoril Mojzesu po smrti onih dveh sinov Aronovih, ko sta se bližala Gospodu in sta umrla;',
        2: 'in rekel je Gospod Mojzesu: Véli Aronu, bratu svojemu, da naj ne hodi vsakteri čas v svetišče za zagrinjalo pred pokrov sprave, ki je na skrinji, da ne umrje; zakaj v oblaku se bom prikazoval nad pokrovom.',
        3: 'S tem pa naj prihaja Aron v svetišče: z mladim juncem v daritev za greh in z ovnom v žgalno daritev.',
        4: 'Sveto platneno suknjo naj obleče in platnene hlače naj ima ob nagoti svoji in s platnenim pasom naj se opaše in s platnenim pokrivalom pokrije: to so sveta oblačila; ko si izkoplje telo v vodi, naj jih obleče.',
        5: 'In od občine sinov Izraelovih naj vzame dva kozla v daritev za greh in enega ovna v žgalno daritev.',
        6: 'In Aron pripelji v daritev za greh junca, ki je za njega, da izvrši poravnavo za sebe in za hišo svojo.',
        7: 'Potem naj vzame tista dva kozla in ju postavi pred Gospodom pri vhodu shodnega šatora.',
        8: 'In Aron naj vrže žreba za tista dva kozla, en žreb za Gospoda in en žreb za azazel.',
        9: 'In Aron naj pripelje kozla, ki ga je zadel žreb za Gospoda, in ga daruje v daritev za greh.',
        10: 'Kozla pa, ki ga je zadel žreb za azazel, naj postavijo živega pred Gospoda, da se stori poravnava nad njim in se pošlje za azazel v puščavo.',
        11: 'Aron torej naj privede v daritev za greh junca, ki je za njega, in naj izvrši poravnavo za sebe in hišo svojo ter zakolje najprej junca v daritev za greh za sebe.',
        12: 'In vzame naj kadilnico polno žerjavice z oltarja, ki je pred Gospodom, in obe prgišči polni blagodišečega kadila, na drobno stolčenega, in nese to noter za zagrinjalo.',
        13: 'In naj položi kadilo na ogenj pred Gospodom, da oblak iz kadila pokrije pokrov sprave, ki je vrhu pričevanja, da ne umrje.',
        14: 'Potem naj vzame junčeve krvi in poškropi s prstom sprednjo stran pokrova proti vzhodu; pred pokrovom pa naj poškropi s tisto krvjo sedemkrat s prstom svojim.',
        15: 'Nato naj zakolje kozla v daritev za greh, ki je za ljudstvo, in nese kri njegovo noter za zagrinjalo ter stori s to krvjo, kakor je storil z junčevo krvjo, in razškropi naj jo na pokrov in pred pokrov:',
        16: 'in tako naj izvrši poravnavo za svetišče zaradi nečistot sinov Izraelovih in zaradi njih prestopkov po vseh njih grehih; in enako naj stori za shodni šator, ki biva med njimi sredi njih nečistot.',
        17: 'Nobenega človeka ne sme biti v shodnem šatoru, kadar gre noter, da stori poravnavo v svetišču, dokler ne pride iz njega. In tako naj izvrši spravo za sebe in za hišo svojo in za ves zbor Izraelovih.',
        18: 'In pride naj ven k oltarju, ki je pred Gospodom, in stori poravnavo zanj; in vzame naj krvi junčeve in krvi kozlove ter pomaže ž njo rogove na oltarju kroginkrog,',
        19: 'in ga poškropi s krvjo s prstom svojim sedemkrat ter ga očisti in posveti od nečistot sinov Izraelovih.',
        20: 'In ko dokonča spravo svetišča in shodnega šatora in oltarja, naj pripelje živega kozla.',
        21: 'In Aron naj položi obe roki svoji živemu kozlu na glavo in pripoznaj nad njim vse krivice sinov Izraelovih in vse njih prestopke po vseh njih grehih; in položi naj jih na glavo kozlu ter ga pošlje po pripravljenem možu v puščavo,',
        22: 'da odnese kozel na sebi vse njih krivice v pusto deželo; zato naj ga odžene v puščavo.',
        23: 'Potem naj stopi Aron v shodni šator in sleče platnena oblačila, ki jih je bil oblekel, ko je šel v svetišče, in naj jih ondi pusti;',
        24: 'in naj si izkoplje telo v vodi na svetem kraju ter obleče oblačila svoja in pride ven in daruje žgalno daritev svojo in žgalno daritev ljudstva in stori poravnavo za sebe in za ljudstvo.',
        25: 'In naj zažge tolstino daritve za greh na oltarju.',
        26: 'In tisti, ki odžene kozla za azazel, naj si opere oblačila in izkoplje telo v vodi; in potem sme priti v taborišče.',
        27: 'A junca in kozla, ki sta bila v daritev za greh, katerih kri je bil Aron nesel za poravnavo v svetišče, naj odneso ven za taborišče, in njiju kožo, meso in blato naj sežgo z ognjem.',
        28: 'In kdor ju sežge, naj si opere oblačila in se izkoplje v vodi; in potem sme priti v taborišče.',
        29: 'In to vam bodi večna postava: Deseti dan sedmega meseca pokorite duše svoje in nobenega dela ne opravljajte, ne domačin, ne tujec, ki biva med vami.',
        30: 'Zakaj ta dan se izvrši sprava za vas, da boste očiščeni; vseh grehov svojih bodete čisti pred Gospodom.',
        31: 'Sobota prazničnega počitka vam bodi ta dan, in pokorite duše svoje; večna postava je to.',
        32: 'Spravo pa naj izvrši duhovnik, ki je bil maziljen in posvečen v duhovnika namesto očeta svojega, in naj obleče platnena oblačila, ki so sveta oblačila,',
        33: 'in stori poravnavo za sveto svetišče in za shodni šator, tudi za oltar naj stori poravnavo, tudi za duhovnike in za vse ljudstvo občine naj izvrši poravnavo.',
        34: 'In to vam bodi večna postava: za sinove Izraelove je storiti spravo zavoljo vseh njih grehov, enkrat v letu. In storil je, kakor je bil Gospod zapovedal Mojzesu.',
    },
    17: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'Govóri Aronu in sinom njegovim in vsem sinovom Izraelovim ter jim reci: To je, kar je zapovedal Gospod, govoreč:',
        3: 'Vsakdo iz hiše Izraelove, ki zakolje vola ali ovco ali kozo v taborišču ali pa zunaj taborišča',
        4: 'ter jih ne prinese k vratom shodnega šatora, da jih daruje kot darilo pred bivališčem Gospodovim: kri se všteje tistemu možu, kri je prelil, in izrebljen bodi tisti mož izmed svojega ljudstva;',
        5: 'zato da prinašajo sinovi Izraelovi klalščine svoje, ki jih darujejo na planem, da jih, pravim, prinašajo Gospodu k vratom shodnega šatora, k duhovniku, in jih koljejo kot mirovne daritve Gospodu.',
        6: 'In razškropi naj duhovnik kri na oltar Gospodov pri vhodu shodnega šatora in zažge tolstino v prijeten duh Gospodu.',
        7: 'In naj ne darujejo klalščin svojih kozlom-malikom, za katerimi hodijo v nečistovanju. Večna postava jim to bodi po njih prihodnjih rodovih.',
        8: 'Zato jim véli: Vsak iz hiše Izraelove in izmed tujcev, ki gostujejo med vami, kdor daruje žgalno ali klalno daritev,',
        9: 'pa je ne prinese k vratom shodnega šatora, da bi jo daroval Gospodu: tisti mož bodi iztrebljen izmed ljudstva svojega.',
        10: 'In vsakdo iz hiše Izraelove in izmed tujcev, ki gostujejo med vami, kdor uživa kakršnokoli kri: obličje obrnem zoper tistega, ki jé kri, in ga iztrebim izmed ljudstva njegovega.',
        11: 'Zakaj duša mesa je v krvi, in jaz sem vam jo dal na oltar, da se ž njo izvrši sprava za duše vaše; kri je namreč, ki spravlja po duši v njej.',
        12: 'Zato sem rekel sinovom Izraelovim: Nobena duša izmed vas ne jej krvi, tudi noben tujec, ki biva med vami, ne jej krvi.',
        13: 'In vsakdo iz hiše Izraelove in izmed tujcev, ki bivajo med vami, ako ulovi kako zverino ali ptico, ki se sme jesti, ta naj izpusti njeno kri in jo pokrije s prstjo.',
        14: 'Zakaj duša vsakega mesa je njega kri, združena z dušo njegovo; zato sem rekel sinovom Izraelovim: Krvi kateregakoli mesa ne smete jesti, kajti duša vsakega mesa je kri njegova; kdorkoli jo užije, bodi iztrebljen.',
        15: 'In vsaka duša, ki bi jedla mrlino ali raztrgano od zveri, bodisi domačin ali tujec, ta naj si opere oblačila in se izkoplje v vodi, in bode nečist do večera; potem je čist.',
        16: 'Ako jih pa ne izpere in mesa svojega ne izkoplje, bo nosil krivico svojo.',
    },
    18: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'Govóri sinovom Izraelovim in jim reci: Jaz sem Gospod, Bog vaš.',
        3: 'Ne delajte, kar delajo v deželi Egiptovski, ki ste v njej prebivali, niti ne počenjajte, kar uganjajo v deželi Kanaanski, v katero vas vodim, in po njih postavah nikar ne živite.',
        4: 'Moje sodbe izpolnjujte in moje postave spoštujte, da po njih živite. Jaz sem Gospod, Bog vaš.',
        5: 'Pazite torej na moje postave in moje sodbe, po katerih bo človek, izpolnjujoč jih, živel. Jaz sem Gospod.',
        6: 'Noben človek naj se ne približa komurkoli iz sorodništva svojega, da bi odgrnil sramoto. Jaz sem Gospod.',
        7: 'Sramote očeta svojega in sramote matere svoje ne odgrni; mati tvoja je, sramote njene ne smeš odkriti.',
        8: 'Sramote žene očeta svojega ne odgrni, sramota je očeta tvojega.',
        9: 'Sramote sestre svoje, hčere očeta svojega ali hčere matere svoje, bodisi doma ali zunaj rojena, sramote njene ne odgrni.',
        10: 'Sramote hčerke sina svojega ali hčerke hčere svoje, sramote njene ne odgrni; kajti tvoja sramota je.',
        11: 'Sramota hčere od žene očeta tvojega, rojene od očeta tvojega, – sestra tvoja je, njene sramote ne odgrni.',
        12: 'Sramote sestre očeta svojega ne odgrni, sorodnica je očeta tvojega.',
        13: 'Sramote sestre matere svoje ne odgrni, ker sorodnica je matere tvoje.',
        14: 'Sramote brata očeta svojega ne odgrni, ženi njegovi se ne približaj, žena je strica tvojega.',
        15: 'Sramote snahe svoje ne odgrni: žena je sinu tvojega, njene sramote ne odkrij.',
        16: 'Sramote žene brata svojega ne odgrni, sramota je brata tvojega.',
        17: 'Sramote žene in hčere njene ne odkrij, hčerke sinú njenega in hčerke njene hčere si ne vzemi, da bi odkrival njiju sramoto: sorodnici sta; krvosramstvo je.',
        18: 'Sestre žene svoje si ne vzemi, da bi v njej zbujal ljubosumnost, odkrivaje nje sramoto zraven te, dokler živi.',
        19: 'In ne približaj se ženi, da odgrneš sramoto njeno, dokler je ločena zaradi nesnage svoje.',
        20: 'Z ženo bližnjega svojega ne lezi v združenje, da bi se ž njo oskrunil.',
        21: 'In iz zaroda svojega ne daj, da bi kdo šel čez ogenj Molohu, in imena Gospoda, Boga svojega, ne onečasti. Jaz sem Gospod.',
        22: 'Z moškim se ne druži, kakor se je družiti z ženo: grdoba je.',
        23: 'Z nobeno živino se ne pečaj, da bi se ž njo oskrunil; tudi ženska naj ne stopi pred nobeno živino, da bi se pečala ž njo: grda oskrumba je.',
        24: 'Ne oskrunite se z nobeno teh reči, zakaj s temi vsemi so se oskrunjali pogani, ki jih preženem pred vami;',
        25: 'tudi dežela se je oskrunila, zato hočem kaznovati njene krivice na njej, in dežela izbljuje prebivalce svoje.',
        26: 'Vi torej izpolnjujte postave moje in sodbe moje in ne delajte nobene teh grdob, ne domačin, ne tujec, ki biva med vami;',
        27: '(zakaj vse te grdobe je uganjalo ljudstvo te dežele, ki je bilo pred vami, in dežela je bila oskrunjena;)',
        28: 'da bi tudi vas dežela ne izbljuvala, ker ste jo oskrunili, kakor je izbljuvala narod, ki je bil pred vami.',
        29: 'Zakaj kdorkoli stori katero teh grdobij, vse duše, ki to delajo, bodo iztrebljene izmed svojega ljudstva.',
        30: 'Na straži torej bodite, da izpolnjujete povelja moja ter ne počenjate nobene tistih grdih navad, ki so jim stregli pred vami, in da se s tem ne oskrunite. Jaz sem Gospod, Bog vaš.',
    },
    19: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'Govóri vsej občini sinov Izraelovih in jim véli: Sveti bodite, zakaj jaz Gospod, Bog vaš, sem svet.',
        3: 'Vsak se boj matere svoje in očeta svojega, in sobote moje praznujte. Jaz sem Gospod, Bog vaš.',
        4: 'Ne obračajte se k ničevim malikom, tudi si ne delajte ulitih bogov: jaz sem Gospod, Bog vaš.',
        5: 'In ko darujete mirovno daritev Gospodu, darujte tako, da boste milo sprejeti.',
        6: 'Použije naj se tisti dan, kadar jo darujete, in drugi dan; če pa kaj preostane do tretjega dne, z ognjem naj se sežge.',
        7: 'Ako bi se pa kako zaužilo tretji dan, gnusoba je, ne bo milo sprejeto;',
        8: 'a kdorkoli bi to jedel, bo nosil krivico svojo, ker je onesvetil svetinjo Gospodovo, in ta duša bo iztrebljena izmed svojega ljudstva.',
        9: 'In ko boste želi žetev zemlje svoje, ne požanji docela obmejkov njive svoje, tudi ne pobiraj ob žetvi popuščenega klasja.',
        10: 'In v vinogradu svojem ne paberkuj ter raztresenih jagod ne pobiraj; pusti jih siromaku in tujcu. Jaz sem Gospod, Bog vaš.',
        11: 'Ne kradite, tudi ne lažite in zvijačno ne ravnajte drug z drugim.',
        12: 'In ne prisegajte lažnivo pri mojem imenu, da bi onečastili ime Boga svojega. Jaz sem Gospod.',
        13: 'Ne opehari bližnjega svojega in ga ne oropaj. Plačilo najemniku tvojemu naj ne ostane pri tebi do jutra.',
        14: 'Glušca ne preklinjaj in slepcu ne stavi spotikljaja, temuč boj se Boga svojega. Jaz sem Gospod.',
        15: 'V pravdi ne ravnajte krivično; ne oziraj se na osebo ubožčevo, tudi ne čislaj osebe mogočnikove, marveč s pravičnostjo sodi bližnjega svojega.',
        16: 'Ne pohajaj kot opravljivec med ljudstvom svojim, in v krvavo sodbo ne spravi bližnjega svojega. Jaz sem Gospod.',
        17: 'Brata svojega ne sovraži v srcu svojem; resno posvari bližnjega svojega, da ne boš nosil greha zaradi njega.',
        18: 'Ne maščuj se, tudi se ne spominjaj krivega zoper otroke ljudstva svojega, ampak ljubi bližnjega svojega kakor samega sebe. Jaz sem Gospod.',
        19: 'Postave moje ohranite. Živini svoje ne puščaj pojati se z živino drugega plemena; njive svoje ne obsevaj z dvoje vrste semenom, in oblačil, stkanih iz dvoje preje, ne oblači.',
        20: 'In kdor bi se telesno združil z žensko, ki je dekla, možu zaročena, pa nikakor ni odkupljena in tudi ne oproščena: naj se jima prisodi kazen; ne bodita umorjena, ker ona ni bila prosta.',
        21: 'On pa naj prinese daritev za krivdo Gospodu k vratom shodnega šatora, ovna v daritev za krivdo.',
        22: 'In duhovnik naj stori poravnavo z ovnom daritve za krivdo pred Gospodom za greh njegov, ki ga je zakrivil; in odpuščen mu bo greh, s katerim se je pregrešil. –',
        23: 'In ko pridete v deželo in zasadite vsake vrste drevesa v živež, prvo njih sadje štejte kot neobrezo; tri leta naj vam bodo kakor neobrezana, ne jejte od njih;',
        24: 'a v četrtem letu bodi vse njih sadje sveto, v zahvalo Gospodu;',
        25: 'v petem letu pa jejte njih sad, da bi se vam pomnožil njih pridelek. Jaz sem Gospod, Bog vaš.',
        26: 'Ničesar ne jejte s krvjo. Ne pečajte se z vedeževanjem, ne s čaranjem.',
        27: 'Ne strizite si na okroglo las na glavi in ne grdite si brade ob kraju.',
        28: 'In zaradi mrtveca si ne delajte zarez v meso in nobenih znamenj si ne vžigajte. Jaz sem Gospod.',
        29: 'Ne onečasti hčere svoje, dopuščajoč, da je nečistnica, da ne bi se dežela vdala nečistovanju in se napolnila nesramnosti.',
        30: 'Sobote moje praznujte in svetišče moje spoštujte. Jaz sem Gospod.',
        31: 'Ne obračajte se k rotilcem mrtvih, ne k vražarjem, ne iščite jih, da bi se po njih oskrunili. Jaz sem Gospod, Bog vaš.',
        32: 'Pred sivo glavo vstani in spoštuj obličje starčkovo, in boj se Boga svojega. Jaz sem Gospod.',
        33: 'In ako gostuje tujec pri tebi v deželi vaši, ga ne smete dreti;',
        34: 'kakor vaš rojak vam bodi tujec, ki biva med vami, in ljubi ga kakor samega sebe; saj ste tudi bili tujci v deželi Egiptovski. Jaz sem Gospod, Bog vaš.',
        35: 'Ne delajte nič krivičnega v sodbi, pri dolgostni meri, pri tehtnici in votli meri;',
        36: 'pravična tehtnica, poštene uteži, poštena efa in pošten hin bodi pri vas. Jaz sem Gospod, Bog vaš, ki sem vas peljal iz dežele Egiptovske.',
        37: 'Pazite torej na vse postave moje in vse sodbe moje ter jih izpolnjujte. Jaz sem Gospod.',
    },
    20: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'Še véli sinovom Izraelovim: Kdorkoli bodi izmed sinov Izraelovih in izmed tujcev, ki gostujejo v Izraelu, ki da iz semena svojega Molohu, mora umreti; ljudstvo domače naj ga posuje s kamenjem.',
        3: 'Tudi jaz hočem obrniti obličje svoje zoper takega človeka in ga iztrebiti izmed ljudstva njegovega, zato ker je dal iz semena svojega Molohu, da bi onečastil svetišče moje ter onesvetil ime svetosti moje.',
        4: 'In če domače ljudstvo zatisne kako oči pred takim človekom, ko je dal iz semena svojega Molohu, da ga ne usmrtijo,',
        5: 'tedaj obrnem jaz obličje svoje zoper tega človeka in zoper rodovino njegovo ter iztrebim izmed njih ljudstva njega in vse, ki gredo v nečistosti za njim, da bi nečistovali z Molohom.',
        6: 'Tudi zoper dušo, ki se obrača k rotilcem mrtvih in k vražarjem, da bi šla v nečistosti za njimi, zoper tako dušo obrnem obličje svoje in ga iztrebim izmed ljudstva njegovega.',
        7: 'Zatorej se posvečujte in bodite sveti, ker jaz sem Gospod, Bog vaš.',
        8: 'In pazite na moje postave ter jih izpolnjujte; jaz sem Gospod, ki vas posvečujem.',
        9: 'Vsakdo, ki preklinja očeta svojega ali mater svojo, mora umreti; svojega očeta in svojo mater je klel, kri njegova bodi nad njim.',
        10: 'In ako kateri mož prešeštvuje z ženo drugega moža, ako prešeštvuje z ženo bližnjega svojega, prešeštnik in prešeštnica morata umreti.',
        11: 'In mož, ki leži z ženo očeta svojega, je odkril sramoto očeta svojega: obadva morata umreti; njiju kri bode nad njima.',
        12: 'In ako kdo leži s snaho svojo, oba morata umreti: grdo oskrumbo sta storila; njiju kri bode nad njima.',
        13: 'In ako kdo leži z moškim, kakor se leži z žensko, oba sta storila grdobnost: morata umreti; njiju kri bode nad njima.',
        14: 'In če si kdo vzame ženo in njeno mater, protinaturnost je: z ognjem naj se sežgo, on in oni, da ne bode protinaturnosti med vami.',
        15: 'In ako kdo leži z živino, mora umreti, tudi živino usmrtite.',
        16: 'In ako bi se žena približala živini, da bi se ž njo pečala, usmrti ženo in živino: morata umreti, njiju kri bode nad njima.',
        17: 'In ako kdo vzame sestro svojo, očeta svojega hčer ali matere svoje hčer, in gleda njeno sramoto in ona gleda sramoto njegovo: rodoskrumba je, in iztrebljena bodita pred očmi otrok naroda svojega; on je odkril sramoto sestre svoje, naj nosi krivico svojo.',
        18: 'In če mož leži z ženo v bolezni njeni in odgrne sramoto njeno, je razgalil njen tok in ona je odkrila tok krvi svoje; oba bodita iztrebljena izmed svojega ljudstva.',
        19: 'In ne odgrni sramote sestri matere svoje in sestri očeta svojega; zakaj tak odkriva nagoto sorodnice svoje: krivico svojo bosta nosila.',
        20: 'In če kdo leži s svojega strica ženo, je odgrnil sramoto strica svojega: nosila bosta krivico svojo, umrjeta brez otrok.',
        21: 'In ako kdo vzame brata svojega ženo, nečistost je; odkril je sramoto brata svojega; brez otrok bodeta.',
        22: 'Pazite torej na vse postave moje in na vse sodbe moje ter jih izpolnjujte, da vas ne izbljuje dežela, v katero vas vodim, da boste v njej prebivali.',
        23: 'In ne živite po navadah poganskega naroda, ki ga ženem izpred vas; kajti vse to so počenjali in s tem so se mi pristudili.',
        24: 'A vam sem rekel: Vi podedujte njih deželo, ker vam jo hočem dati, da jo posedete, deželo, ki v njej teče mleko in med. Jaz sem Gospod, Bog vaš, ki sem vas ločil od drugih ljudstev.',
        25: 'Ločite torej tudi vi med čisto živino in nečisto in med nečistimi pticami in čistimi, da se ne oskrunite z živino ali letečino ali s čimerkoli, kar lazi po zemlji, kar sem izločil, da naj štejete za nečisto.',
        26: 'In sveti bodite meni, ker svet sem jaz Gospod, in sem vas ločil izmed ljudstev, da bi bili moji.',
        27: 'Tudi če ima mož ali žena duha, ki se peča z rotenjem mrtvih ali vražarstvom, morata umreti: s kamenjem naj ju posujejo; njiju kri bode nad njima.',
    },
    21: {
        1: 'In Gospod reče Mojzesu: Govóri duhovnikom, sinovom Aronovim, ter jim véli: Pri mrliču naj se nihče izmed vas ne oskruni med ljudstvom svojim;',
        2: 'samo pri bližjih sorodnikih svojih, pri materi in pri očetu, pri sinu in pri hčeri, pri bratu',
        3: 'in pri sestri, devici, ki biva pri njem, ko se še ni omožila: pri teh se sme onečistiti.',
        4: 'Ne oskruni se naj, ker je gospod med svojim ljudstvom, da bi se onesvetil.',
        5: 'Ne strižejo naj si pleše na glavi in ne brijejo ob kraju brade svoje, in na telesu naj si ne delajo nobenih zarez.',
        6: 'Sveti naj bodo Bogu svojemu in naj ne onesvetijo imena Boga svojega, zakaj ognjene daritve Gospodove, kruh Boga svojega, darujejo; zato naj bodo sveti.',
        7: 'Nečistnice in posiljene deve naj si ne jemljejo, tudi ne take, katero je njen mož odpahnil; zakaj duhovnik je svet Bogu svojemu.',
        8: 'Zatorej ga štej za svetega, kajti daruje kruh Boga tvojega; svet ti bodi, ker jaz sem svet, Gospod, ki vas posvečujem.',
        9: 'Hči duhovnikova pa, ki se onesveti z nečistovanjem, onesveti očeta svojega: z ognjem bodi sežgana.',
        10: 'Tisti pa, ki je veliki duhovnik med brati svojimi, na čigar glavo je bilo izlito olje maziljenja in ki je bil posvečen, da se oblači v sveta oblačila: naj si ne razkriva glave ter ne trga oblačil;',
        11: 'tudi naj ne hodi k truplu mrtvemu, niti pri očetu svojem ali pri materi svoji naj se ne onečisti.',
        12: 'In iz svetišča naj ven ne hodi, tudi ne onesveti svetišča Boga svojega, zakaj posvetitev mazilnega olja Boga svojega ima na sebi. Jaz sem Gospod.',
        13: 'In ženo naj si vzame v devištvu njenem.',
        14: 'Vdove in ločene ženske in posiljene, nečistnice, teh naj ne vzame, ampak devico iz ljudstva svojega naj vzame za ženo.',
        15: 'In semena svojega naj ne onesveti med ljudstvom svojim, zakaj jaz sem Gospod, ki ga posvečujem.',
        16: 'In Gospod je govoril Mojzesu, rekoč:',
        17: 'Govóri Aronu in reci: Kdorkoli iz semena tvojega po prihodnjih rodovih ima telesno hibo na sebi, naj ne pristopa darovat kruha Boga svojega;',
        18: 'kajti nihče, na komer je telesna hiba, ne sme pristopiti: slepec ali hromec, ali kdor ima ploščat nos ali katerikoli ud prevelik,',
        19: 'ali mož, ki ima zlomljeno nogo ali zlomljeno roko,',
        20: 'ali kdor je grbav ali pritlikav, ali kdor ima madež v očesu, ali kdor ima garje ali lišaj ali stlačen modnik.',
        21: 'Nihče iz semena Arona duhovnika, ki ima kako hibo, naj ne pristopa darovat ognjene daritve Gospodove; hiba je na njem, ne sme pristopiti, da daruje kruh Boga svojega.',
        22: 'Kruh Boga svojega sme uživati, od presvetega in od svetega,',
        23: 'samo za zagrinjalo naj ne hodi in k oltarju naj ne pristopa, ker ima hibo, da ne onesveti svetišč mojih: zakaj jaz sem Gospod, ki jih posvečujem.',
        24: 'In Mojzes je tako govoril Aronu in sinovom njegovim in vsem sinovom Izraelovim.',
    },
    22: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'Véli Aronu in sinom njegovim, da naj zdržljivo rabijo svete reči, ki jih sinovi Izraelovi meni posvečujejo, in svetega imena mojega naj ne onečaščajo: jaz sem Gospod.',
        3: 'Reci jim: Kdorkoli iz semena vašega po vseh prihodnjih rodovih vaših se približa svetim rečem, ki jih sinovi Izraelovi posvečujejo Gospodu, ko ima nečistoto svojo na sebi, ta duša bodi iztrebljena izpred obličja mojega. Jaz sem Gospod.',
        4: 'Vsak iz semena Aronovega, ki je gobav ali ima tok, naj ne uživa svetih reči, dokler ni čist. In kdor se dotakne česarkoli, kar je nečisto od mrtveca, ali njega, ki ima semenotok,',
        5: 'ali kdor se dotakne katere golazni, ki onečiščuje, ali človeka, od katerega lahko naleze nečistoto, kakršnakoli bodi nečistota njegova:',
        6: 'tisti, ki se takega dotakne, nečist bode do večera; in ne uživa naj svetih reči, temuč izkoplji telo svoje v vodi.',
        7: 'In ko zajde solnce, bode čist, in potem sme jesti od svete reči, ker to mu je v živež.',
        8: 'Mrline in raztrganega živinčeta ne jej nihče, da bi se s tem ognusil. Jaz sem Gospod.',
        9: 'Pazijo naj torej, da izpolnijo povelja moja, da si ne nakopljejo greha ter vsled tega umrjo, ker so oskrunili sveto. Jaz sem Gospod, ki jih posvečujem.',
        10: 'Noben tujec naj ne jé svetih reči; gostač in najemnik duhovnikov ne smeta jesti svetega.',
        11: 'Ako pa duhovnik kupi koga za denar, ta sme jesti od tega; in kateri so rojeni v hiši njegovi, naj uživajo kruh njegov.',
        12: 'In če se duhovnikova hči omoži s tujcem, ne sme jesti od podviga svetih reči.',
        13: 'Ako je pa duhovnikova hči ovdovela ali se ločila in nima otrok, pa se vrne v hišo očeta svojega in tu biva kakor v mladosti svoji, sme jesti kruh očeta svojega; ali noben tujec naj ne jé od njega.',
        14: 'Kdor bi pa jedel sveto ponevedoma, naj pridene peti del k temu in povrne duhovniku tisto sveto reč.',
        15: 'Nikar naj duhovniki ne oskrunijo svetih reči, ki jih sinovi Izraelovi poklanjajo Gospodu,',
        16: 'da jih ne obremene s krivico krivde, ko uživajo njih svete reči; zakaj jaz sem Gospod, ki jih posvečujem.',
        17: 'In Gospod je govoril Mojzesu, rekoč:',
        18: 'Govori Aronu in sinom njegovim in vsem sinom Izraelovim ter jim reci: Kdorkoli iz hiše Izraelove in izmed tujcev v Izraelu prinese darilo svoje, bodisi kaj obljubljenega ali kaj prostovoljnega, kar prinašajo Gospodu v žgalno daritev:',
        19: 'da bi bili milo sprejeti, darujte brezhibnega samca, od govedi, od ovac ali koz.',
        20: 'Ničesar takega, na čemer je hiba, ne darujte, ker ne bo blagovoljno sprejeto za vas.',
        21: 'In če kdo prinese mirovno daritev Gospodu, da izpolni posebno obljubo, ali kot prostovoljno darilo, od govedi ali drobnice: bodi popolno, da bi bilo milo sprejeto, nobene hibe naj ne bo na tem.',
        22: 'Slepo ali polomljeno ali pohabljeno ali kozavo ali garjavo ali krastavo: teh ne prinašajte Gospodu in teh ne devajte v ognjeno daritev na oltar za Gospoda.',
        23: 'Govedo ali ovco, ki ima predolg ali prekratek kak ud, smeš darovati kot prostovoljen dar, ali kot izpolnitev obljube ne bo milo sprejeto.',
        24: 'Ujalovljenega s stisnjenjem ali zmečkanjem ali odtrganjem ali skopljenjem ne darujte Gospodu, in kaj takega ne delajte v svoji deželi.',
        25: 'Tudi iz tujčeve roke ne darujte nič takega kot kruh Boga svojega; zakaj pokvara, hiba je na tem, ne bo milo sprejeto za vas.',
        26: 'In Gospod je govoril Mojzesu, rekoč:',
        27: 'Ko se stori tele, ovca ali koza, naj ostane sedem dni pri materi svoji, od osmega dne pa in poslej bode ugodno za darilo v ognjeno daritev Gospodu.',
        28: 'Bodisi pa krava ali ovca, nje in njenega mladiča ne koljite isti dan.',
        29: 'In ko darujete zahvalno daritev Gospodu, darujte jo tako, da boste milo sprejeti.',
        30: 'Tisti dan jo zaužijte, nič je ne pustite do jutra; jaz sem Gospod.',
        31: 'Pazite torej na moje zapovedi in jih izpolnjujte. Jaz sem Gospod.',
        32: 'In ne onesvečujte imena svetosti moje, da bom posvečen med sinovi Izraelovimi. Jaz sem Gospod, ki vas posvečujem,',
        33: 'ki sem vas odpeljal iz dežele Egiptovske, da bi vam bil Bog. Jaz sem Gospod.',
    },
    23: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'Govori sinom Izraelovim in jim reci: Prazniki Gospodovi, ki jih razglasite za sveta zborovanja, le-ti so prazniki moji.',
        3: 'Šest dni naj se opravlja delo, a sedmi dan je sobota prazničnega počitka, sveto zborovanje; nobenega posla ne opravljajte: počitek je Gospodu po vseh prebivališčih vaših.',
        4: 'To so prazniki Gospodovi, sveta zborovanja, ki jih razglasíte v njih določenih časih.',
        5: 'Prvi mesec, štirinajsti dan meseca proti večeru, je pasha Gospodova.',
        6: 'In petnajsti dan tega meseca je praznik opresnih kruhov Gospodu: sedem dni jejte opresnine.',
        7: 'Prvi dan imejte sveto zborovanje; nobenega službenega dela ne opravljajte.',
        8: 'In sedem dni darujte ognjene daritve Gospodu; sedmi dan je sveto zborovanje, nobenega službenega dela ne opravljajte.',
        9: 'In Gospod je govoril Mojzesu, rekoč:',
        10: 'Govóri sinovom Izraelovim in jim véli: Ko pridete v deželo, ki vam jo jaz dam, in boste želi letino njeno, prinesite prvi snop žetve svoje k duhovniku.',
        11: 'In on majaj snop pred Gospodom, da bo milo sprejet za vas; zjutraj po soboti naj ga maja duhovnik.',
        12: 'Tisti dan pa, ko darujete snop z majanjem, prinesite brezhibno enoletno jagnje v žgalno daritev Gospodu;',
        13: 'in ž njo vred jedilno daritev: dve desetinki bele moke, pomešane z oljem, kot ognjeno daritev Gospodu v prijeten duh; in ž njo vred pitno daritev: vina, četrtino hina.',
        14: 'A kruha in opraženega zrnja in svežega žita ne jejte prav do tistega dne, ko prinesete darilo Bogu svojemu: večna postava je to za prihodnje rodove vaše po vseh prebivališčih vaših.',
        15: 'Potem štejte od prvega dne po soboti, od dneva, ko ste prinesli snop v dar majanja, sedem celih tednov naj bode;',
        16: 'do jutra po sedmi soboti štejte petdeset dni, in tedaj darujte novo jedilno daritev Gospodu.',
        17: 'Iz prebivališč svojih prinesite dva hleba za majanje, iz dveh desetink bele moke, pečena s kvasom, kot prvine Gospodu.',
        18: 'In s kruhom vred prinesite sedem brezhibnih, enoletnih jagnjet in mladega junca in dva ovna, ki naj bodo v žgalno daritev Gospodu, in obenem jedilno in pitno daritev, ki k njim gre: ognjena žrtev bodi v prijeten duh Gospodu.',
        19: 'In darujte kozla v daritev za greh in dve enoletni jagnjeti v mirovno daritev.',
        20: 'In majaj jih duhovnik s kruhom prvin kot daritev majanja pred Gospodom z dvema jagnjetoma vred: sveti naj bodo Gospodu v prid duhovniku.',
        21: 'In razglasite istega dne: Sveto zborovanje vam bodi, nobenega službenega dela ne opravljajte! Večna postava bode to po vseh prebivališčih vaših od roda do roda. –',
        22: 'In ko žanjete letino dežele svoje, ne požanji docela obmejkov njive svoje in ne pobiraj ob žetvi popuščenega klasja: pusti jih ubožcu in tujcu. Jaz sem Gospod, Bog vaš.',
        23: 'In Gospod je govoril Mojzesu, rekoč:',
        24: 'Govóri sinom Izraelovim in reci: Prvi dan sedmega meseca vam bodi slavnosten počitek, spomin s trobentanjem, sveto zborovanje.',
        25: 'Nikakršnega službenega posla ne opravljajte in darujte ognjeno daritev Gospodu.',
        26: 'In Gospod je govoril Mojzesu, rekoč:',
        27: 'Ali deseti dan tega sedmega meseca je slavnostni dan sprave: sveto zborovanje imejte in pokoríte duše svoje ter darujte ognjeno daritev Gospodu.',
        28: 'Nobenega dela ne opravljajte tisti dan, zakaj slavnostni dan sprave je, da se izvrši poravnava za vas pred Gospodom, Bogom vašim.',
        29: 'Kajti vsaka duša, ki se ne pokori tisti dan, bodi iztrebljena izmed ljudstva svojega.',
        30: 'In vsako dušo, ki bi opravljala kakršnokoli delo tisti dan, hočem pogubiti izmed njenega ljudstva.',
        31: 'Nobenega dela ne opravljajte: večna je to postava za prihodnje rodove vaše po vseh prebivališčih vaših.',
        32: 'Sobota prazničnega počitka vam bodi, in pokorite duše svoje, na večer devetega dne meseca, od večera do večera praznujte soboto svojo.',
        33: 'In Gospod je govoril Mojzesu, rekoč:',
        34: 'Govóri sinom Izraelovim in reci: Petnajsti dan tega sedmega meseca je praznik šatorov sedem dni Gospodu.',
        35: 'Prvi dan bodi sveto zborovanje, nobenega službenega dela ne opravljajte.',
        36: 'Sedem dni darujte ognjeno daritev Gospodu, osmi dan imejte sveto zborovanje in darujte ognjeno daritev Gospodu; slovesno zborovanje je, nobenega službenega dela ne opravljajte.',
        37: 'To so prazniki Gospodovi, ki jih razglasite za sveta zborovanja, da se daruje ognjena daritev Gospodu, žgalna in jedilna, klalna in pitna daritev, kolikor je za vsak dan določeno,',
        38: 'razen sobot Gospodovih in razen drugih daril vaših in razen vseh vaših obljub in razen vseh prostovoljnih daritev, ki jih dajete Gospodu.',
        39: 'Ali petnajsti dan sedmega meseca, ko boste spravili pridelke zemlje, obhajajte praznik Gospodov sedem dni; prvi dan bodi prazničen počitek in osmi dan bodi prazničen počitek.',
        40: 'In prvi dan si vzemite sadja žlahtnih dreves in palmovih mladik in vej z listnatih dreves in vrbja od potoka, in veselite se pred Gospodom, Bogom svojim, sedem dni.',
        41: 'In obhajajte to kot praznik Gospodu sedem dni v letu: večna to je postava za prihodnje rodove vaše; v sedmem mesecu praznujte to.',
        42: 'In prebivali boste v šatorih iz zelenja sedem dni; vsak, kdor se je rodil v Izraelu, naj prebiva v šatorih:',
        43: 'da bi vedeli prihodnji rodovi vaši, da sem dal sinovom Izraelovim prebivati v šatorih, ko sem jih vodil iz dežele Egiptovske. Jaz sem Gospod, Bog vaš.',
        44: 'In naznanil je Mojzes praznike Gospodove sinovom Izralovim.',
    },
    24: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'Ukaži sinovom Izraelovim, naj ti prineso čistega, iztolčenega oljkovega olja za svetilo, da bi gorele svetilnice neprestano.',
        3: 'Zunaj zagrinjala, ki visi pred pričevanjem, v shodnem šatoru naj jih postavlja Aron, da svetijo od večera do jutra pred Gospodom neprestano: večna to bodi postava za prihodnje rodove vaše.',
        4: 'Na čistem svečniku naj razpostavlja svetilnice pred Gospodom neprestano.',
        5: 'In vzemi bele moke in speci iz nje dvanajst hlebov; iz dveh desetink bodi vsak hleb.',
        6: 'In polóži jih v dve vrsti, po šest na vrsto, na čisto mizo pred Gospodom.',
        7: 'In vrh vsake vrste deni čistega kadila, ki bodi kruhov spomin, ognjena daritev Gospodu.',
        8: 'Vsako soboto naj jih razvršča duhovnik pred Gospodom neprestano; od strani sinov Izraelovih je to večna zaveza.',
        9: 'In naj bodo Aronovi in sinov njegovih, da jih jedo na svetem kraju; zakaj to je presveto njemu od ognjenih daritev Gospodovih po večni določbi.',
        10: 'In pride sin izraelske žene, čigar oče pa je bil Egipčan, med sinove Izraelove, in spreta se v taborišču sin izraelske žene in neki Izraelec.',
        11: 'In sin izraelske žene zasramuje ime Božje in preklinja. Pa ga pripeljejo k Mojzesu. In materi njegovi je bilo ime Šelomita, hči Dibrijeva, iz Danovega rodu.',
        12: 'In ga denejo v zapor, dokler ne prejmejo odgovora, kaj veli Gospod.',
        13: 'Tedaj ogovori Gospod Mojzesa, rekoč:',
        14: 'Izpelji tistega preklinjalca ven iz taborišča, in vsi, ki so ga slišali, naj mu položé roke svoje na glavo, in naj ga vsa občina posuje s kamenjem.',
        15: 'Sinom Izraelovim pa sporóči, govoreč: Kdorkoli preklinja Boga svojega, bo nosil greh svoj.',
        16: 'In kdor zasramuje ime Gospodovo, mora umreti; brez ugovora naj ga vsa občina omeče s kamenjem: tujca in rojaka, ko zasramuje to ime, naj usmrte.',
        17: 'In kdor ubije kateregakoli človeka, mora umreti;',
        18: 'kdor pa ubije katero živino, jo mora povrniti: življenje za življenje.',
        19: 'In kdor povzroči poškodbo bližnjemu svojemu, naj se mu stori, kakor je storil:',
        20: 'rano za rano, oko za oko, zob za zob; kakor je prizadel poškodbo človeku, tako naj se mu povrne.',
        21: 'Kdor torej ubije živino, naj se pobota, kdor pa ubije človeka, naj umrje.',
        22: 'Ista sodba bodi pri vas za tujca in za rojaka; zakaj jaz sem Gospod, Bog vaš.',
        23: 'In Mojzes sporoči to sinovom Izraelovim. In izpeljejo tistega, ki je preklinjal, ven iz šatorišča ter ga posujejo s kamenjem. In storili so sinovi Izraelovi, kakor je bil Gospod zapovedal Mojzesu.',
    },
    25: {
        1: 'In Gospod je govoril Mojzesu na gori Sinaju, rekoč:',
        2: 'Govori sinovom Izraelovim ter jim reci: Ko pridete v deželo, ki vam jo jaz dam, naj praznuje dežela soboto Gospodu.',
        3: 'Šest let obsevaj njivo svojo in šest let obrezuj vinograd svoj in spravljaj sadove njegove,',
        4: 'ali sedmo leto naj dobi dežela soboto prazničnega počitka, čas počitka Gospodu: njive svoje ne obsevaj in vinograda svojega ne obrezuj.',
        5: 'Kar ti samo od sebe zraste po zadnji žetvi, ne žanji, in grozdja neobrezane trte svoje ne spravljaj: leto prazničnega počitka naj bode zemlji.',
        6: 'In sobotni obrodek dežele vam bodi v jed, tebi in hlapcu tvojemu in dekli tvoji, in najemniku tvojemu in tujcu, ki biva pri tebi;',
        7: 'tudi živini tvoji in zverini, ki je v tvoji deželi, bodi v živež ves njen obrodek.',
        8: 'Dalje si štej sedmero sobotnih let, sedem let sedemkrat, da ti bode dni sedmerih sobotnih let devetinštirideset let.',
        9: 'In daj glasno trobentati deseti dan sedmega meseca; na dan sprave naj se razlega trobenta po vsej deželi vaši.',
        10: 'In posvetite petdeseto leto in razglasite svobodo po deželi vsem prebivalcem njenim; leto veselega trobentanja vam bodi, ko naj se vsakdo vrne k lastnini svoji in vsakdo zopet pride k rodovini svoji.',
        11: 'Leto veselega trobentanja vam bodi tisto petdeseto: ne sejte in ne žanjite tega, kar samo v njem zraste, in grozdja neobrezanih trt ne trgajte v njem.',
        12: 'Zakaj leto veselega trobentanja je, sveto vam bodi; kar obrodi, uživajte kar ž njive.',
        13: 'V tem milostnem letu naj vsakdo zopet posede lastnino svojo.',
        14: 'In če kaj prodaste bližnjemu ali kaj kupite od bližnjega svojega, ne smete drug drugega opehariti.',
        15: 'Po številu let od milostnega leta kupi od bližnjega svojega in po število letin naj ti proda.',
        16: 'Čim več bode let, tem večja bodi kupnina, in čim manj let, tem manjša bodi; kajti število žetev se prodaja.',
        17: 'Zato naj nihče ne opehari bližnjega svojega, temuč boj se Boga svojega; zakaj jaz sem Gospod, Bog vaš.',
        18: 'Izpolnjujte torej moje postave in pazite na moje pravice in ravnajte po njih, in brezskrbno boste prebivali v deželi.',
        19: 'In zemlja bo rodila sad svoj, in jedli boste dositega in prebivali v njej brez skrbi.',
        20: 'Če pa porečete: Kaj bomo jedli sedmo leto? glej, ne bomo sejali, ne spravljali pridelkov svojih!',
        21: 'Zapovem, da vam pride blagoslov moj v šestem letu, in obrodi pridelkov za tri leta;',
        22: 'in boste sejali v osmem letu in jedli stare pridelke do devetega leta; dokler ne dozore njegovi pridelki, boste jedli starino.',
        23: 'In zemlja naj se ne prodaja za vselej, zakaj moja je zemlja, ker vi ste tujci in priseljenci pri meni.',
        24: 'Zato dovolite po vsej deželi posestva svojega, da se zemlja odkupi.',
        25: 'Ako obuboža brat tvoj in proda kaj posesti svoje, naj pride odkupitelj njegov, njemu najbližji sorodnik, in odkupi prodani del brata svojega.',
        26: 'Ako bi pa komu ne bilo odkupitelja, pa si sam opomore in pridobi, kolikor je treba v odkup:',
        27: 'naj šteje, na koliko let je prodal, in ostala leta poplačaj njemu, komur je prodal, in tako naj zopet dobi posest svojo.',
        28: 'Ako pa ne premore toliko, kolikor bi moral povrniti, naj ostane njegova prodana stvar kupcu v rokah do milostnega leta; in v milostnem letu se stvar oprosti, in on dobi zopet posest svojo.',
        29: 'Ako kdo proda hišo v mestu z obzidjem, naj jo sme odkupiti do konca leta, v katerem jo je prodal; celo leto imej pravico do odkupa.',
        30: 'Če je pa ne odkupi, ko preteče celo leto, naj ostane hiša v mestu z obzidjem v lasti njemu, ki jo je kupil, za prihodnje rodove; ne more se rešiti v milostnem letu.',
        31: 'Toda hiše v vaseh, ki nimajo obzidja, naj se prištevajo njivam na deželi: smejo se odkupiti in v milostnem letu naj bodo proste.',
        32: 'Kar se pa tiče mest levitov, hiš v mestih njih posesti, vselej ostani levitom pravica do odkupa.',
        33: 'In če kdo izmed levitov ne odkupi, v milostnem letu naj mu zopet pripade hiša, ki je bila prodana v mestu posesti njegove; kajti hiše v levitskih mestih so njih posestvo med sinovi Izraelovimi.',
        34: 'Tudi polje v okolici njih mest se ne sme prodajati, ker jim je to večna posest.',
        35: 'In ako brat tvoj poleg tebe obuboža in mu roka opeša, podpiraj ga, kakor tujec in naselnik naj živi pri tebi.',
        36: 'Ne jemlji od njega zakupnine in obresti, temuč boj se Boga svojega, da živi brat tvoj pri tebi.',
        37: 'Denarja svojega mu ne dajaj na obresti in hrane svoje ne zaradi dobička.',
        38: 'Jaz sem Gospod, Bog vaš, ki sem vas peljal iz dežele Egiptovske, da bi vam dal deželo Kanaansko, da bi vam bil za Boga.',
        39: 'In ako brat tvoj obuboža poleg tebe in se ti proda, ne sili ga, naj ti služi za sužnja;',
        40: 'kakor najemnik in kakor naselnik bodi pri tebi, do milostnega leta.',
        41: 'Tedaj naj odide prost od tebe, on in otroci njegovi ž njim, in se vrne zopet k rodovini svoji in zopet dobi posest očetov svojih.',
        42: 'Zakaj moji hlapci so, ki sem jih peljal iz dežele Egiptovske: ne smeš jih prodajati kakor sužnje.',
        43: 'Ne bodi mu neusmiljen gospodar, temuč boj se svojega Boga.',
        44: 'In kar se tiče sužnjev in sužnic, ki jih boš imel: izmed narodov, ki bodo okoli vas, smete kupovati sužnje in sužnice.',
        45: 'Tudi od priseljencev, ki bivajo pri vas, jih smete kupovati, in od njih rodovine, ki so jo rodili v deželi vaši, in bodo naj lastnina vaša;',
        46: 'ne smete jih zapustiti kot dediščino otrokom svojim za sabo, da jim bodo v lastnino. Ti naj vam hlapčujejo za vselej; ali bratom svojim, sinovom Izraelovim, brat svojemu bratu, ne smete neusmiljeno gospodovati.',
        47: 'Ako pa obogati tujec ali priseljenec pri tebi, in brat tvoj obuboža poleg njega in se proda tujcu, priseljencu pri tebi, ali pa komu iz zaroda tujčevega:',
        48: 'naj mu ostane pravica do odkupa, eden bratov njegovih naj ga odkupi;',
        49: 'ali stric njegov ali stričev sin, ali kdorkoli mu je bližnji iz rodbine njegove, naj ga odreši; ali pa če si opomore, naj se sam odkupi.',
        50: 'In naj računi s kupcem svojim od leta, ko se mu je prodal, do milostnega leta, in prodajna cena naj se odmeri po številu let; kakor najemniku naj se mu štejejo dnevi, kolikor jih je odslužil.',
        51: 'Če je še dosti let, njim primerno naj poplača za odkup od denarja, s katerim je bil kupljen;',
        52: 'in če ostaja malo let do milostnega leta, naj mu zaračuni to: proti letom naj poplača ceno odrešitve svoje.',
        53: 'Kakor najemnik leto za letom naj bode pri njem; oni mu ne bodi neusmiljen gospodar, tebi pred očmi.',
        54: 'In ako ne bo odkupljen na ta način, naj odide prost v milostnem letu, on in otroci njegovi ž njim.',
        55: 'Meni namreč so hlapci sinovi Izraelovi, moji hlapci so, ki sem jih peljal iz dežele Egiptovske. Jaz sem Gospod, Bog vaš.',
    },
    26: {
        1: 'Ne delajte si malikov, tudi si ne postavljajte rezanih podob ali kipov in ne poslikanih kamenov v deželi svoji, da bi pred njimi molili; zakaj jaz sem Gospod, Bog vaš.',
        2: 'Sobote moje praznujte in svetišče moje spoštujte. Jaz sem Gospod.',
        3: 'Ako boste živeli po postavah mojih in hranili zapovedi moje ter jih izpolnjevali,',
        4: 'vam bom dajal dež o pravem času, in zemlja bo rodila sad svoj in drevje na polju sadje svoje.',
        5: 'In mlatitev vam bo trajala do trgatve in trgatev bo trajala do setve, in jedli boste kruh svoj dositega in brez skrbi prebivali v deželi svoji.',
        6: 'In dam mir po deželi vaši, da boste spali in ne bo nikogar, ki bi vas strašil; in storim, da izginejo hude zverine iz pokrajine vaše, in meč ne pojde čez deželo vašo.',
        7: 'In podili boste sovražnike svoje, in padali bodo pred vami od meča;',
        8: 'pet izmed vas jih bo podilo sto, in sto vaših jih bo podilo deset tisoč, in padali bodo pred vami pod mečem.',
        9: 'Oziral se bom na vas in storim vas rodovitne ter vas razmnožim in vzdržim zavezo svojo z vami.',
        10: 'In jedli boste stare pridelke, dolgo shranjene, in stare na stran devali pred novimi.',
        11: 'In postavim prebivališče svoje sredi vas, in duša moja vas ne bo mrzila.',
        12: 'In izprehajal se bom med vami, in bodem vam Bog, vi pa bodete ljudstvo moje.',
        13: 'Jaz sem Gospod, Bog vaš, ki sem vas odpeljal iz dežele Egipčanov, da jim ne bodete sužnji; in zlomil sem spone jarma vašega ter vas vzravnal, da hodite pokoncu.',
        14: 'Ako pa me ne boste poslušali in ne boste izpolnjevali vseh teh zapovedi,',
        15: 'nego boste zaničevali postave moje in duša vaša bo mrzila sodbe moje, tako da ne boste izpolnjevali vseh zapovedi mojih, temuč v nič devali zavezo mojo,',
        16: 'hočem tudi jaz to storiti vam: izročim vas v oblast strahu, sušici in vročici, ki povzročajo, da ugasnejo oči in gine duša; in zaman boste sejali seme svoje, ker sovražniki vaši ga použijejo.',
        17: 'In obrnem obličje svoje zoper vas, da boste poraženi pred sovražniki svojimi, in sovražilci vaši vam bodo gospodovali, in bežali boste, ne da bi vas kdo podil.',
        18: 'Če me pa po vsem tem še ne boste poslušali, vas hočem sedemkrat bolj kaznovati za grehe vaše,',
        19: 'in potrem vaše moči prevzetnost in storim, da vam bode nebo kakor železo in zemlja kakor bron;',
        20: 'in moči svoje boste trošili brezuspešno, in zemlja vam ne bo dajala pridelkov svojih in drevje v deželi ne prinašalo sadja svojega.',
        21: 'In če mi boste na zoper živeli, ne hoteč me poslušati, pridenem sedemkrat več udarcev po grehih vaših.',
        22: 'In pošljem nad vas poljske zveri, da vam ugrabijo otroke ter vam požro črede in zmanjšajo število vaše, in ceste vaše postanejo puste.',
        23: 'In če se po takem še ne boste popravili meni pogodi in mi boste na zoper živeli,',
        24: 'hočem tudi jaz vam nasprotovati in vas udarim tudi jaz sedemkrat za grehe vaše.',
        25: 'In pošljem nad vas meč, ki bode maščevalec zaveze moje; in ko se zberete v mestih svojih, pošljem kugo med vas, da boste izdani sovražniku v pest.',
        26: 'Ko strem podporo kruha vašega, vam bo deset žen peklo kruh v eni peči in vam ga bodo oddajale na tehtnico, in jedli boste, pa se ne nasitite.',
        27: 'In če me po vsem tem ne boste poslušali in mi še na zoper živeli,',
        28: 'vam hočem tudi jaz nasprotovati v togoti, in kaznoval vas bom sedemkrat za grehe vaše.',
        29: 'In jedli boste meso sinov svojih in hčer svojih meso boste uživali.',
        30: 'In zatreti hočem višave vaše in uničiti solnčne stebre vaše, in vržem mrtva trupla vaša na trupla grdih malikov vaših, in duša moja vas bo mrzila.',
        31: 'In porušim mesta vaša ter opustošim svetišča vaša, in ne bom maral duhati prijetnih dišav vaših.',
        32: 'In opustošim deželo vašo, da bodo strmeli nad njo sovražniki vaši, prebivajoči v njej.',
        33: 'Vas pa hočem razkropiti med narode in potegniti meč za vami, in dežela vaša bode pusta in mesta vaša postanejo samote.',
        34: 'Tedaj se naužije zemlja sobot svojih; vse dni opustošenja svojega, dokler bodete v deželi sovražnikov svojih, bo počivala zemlja in bo poravnala sobote svoje;',
        35: 'vse dni opustošenja svojega bo imela počitek, počitek, ki ga ni imela ob sobotnih letih vaših, ko ste prebivali v njej.',
        36: 'In kolikor jih izmed vas preostane, v njih srca denem plašljivost v pokrajinah njih sovražnikov, da jih plaši šumenje letečega listja ter bodo bežali kakor pred mečem in padali, dasi jih nihče ne podi;',
        37: 'in spotikali se bodo drug ob drugega, bežeč kakor pred mečem, ne da bi jih kdo podil; in ne boste si upali stati pred sovražniki svojimi.',
        38: 'In poginete med poganskimi narodi in dežela sovražnikov vaših vas požre.',
        39: 'In kar vas preostane, bodo sahnili v krivici svoji v pokrajinah sovražnikov vaših, in tudi v krivicah očetov svojih bodo sahnili ž njimi vred.',
        40: 'In pripoznali bodo krivico svojo in krivico očetov svojih po nezvestobi, ki so jo zakrivili proti meni, pa tudi, ker so mi na zoper živeli,',
        41: 'da sem i jaz jim nasprotoval in jih odpeljal v njih sovražnikov deželo. Ako se tedaj poniža njih neobrezano srce in bo tedaj dosti kaznjena njih krivda:',
        42: 'spomnim se zaveze svoje z Jakobom, pa tudi zaveze svoje z Izakom in zaveze svoje z Abrahamom se spomnim, in dežele se spomnim.',
        43: 'Zakaj dežela bo zapuščena od njih in bo uživala sobote svoje, ležeč pusta in daleč od njih; in dosti bo kaznjena njih krivda zato, prav zato, ker so zametali sodbe moje in so se njih duši gnusile postave moje.',
        44: 'A tudi še takrat, ko bodo v deželi sovražnikov svojih, jih ne zavržem in se mi ne bodo pristudili, da bi jih celo pokončal in uničil zavezo ž njimi; zakaj jaz sem Gospod, njih Bog.',
        45: 'Spomnim se torej njim v prid zaveze svoje s predniki, ki sem jih peljal iz dežele Egiptovske pred očmi poganov, da naj bi jim bil Bog. Jaz sem Gospod.',
        46: 'To so postave moje in sodbe in ukazi, ki jih je postavil Gospod med seboj in sinovi Izraelovimi na gori Sinaju po Mojzesu.',
    },
    27: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'Govori sinovom Izraelovim in jim reci: Če kdo stori obljubo, po cenitvi tvoji naj bodo osebe Gospodove.',
        3: 'Bode pa cenitev tvoja za moškega od dvajsetega leta do šestdesetega leta: petdeset seklov srebra, po seklu svetišča;',
        4: 'ako je pa ženska, bodi cenitev tvoja trideset seklov;',
        5: 'in če je od petih let do dvajsetih let, bodi cenitev tvoja za moškega dvajset seklov in za žensko deset seklov;',
        6: 'in če je v starosti od enega meseca do petih let, bodi cenitev tvoja za moškega pet seklov srebra in za žensko tri sekle srebra;',
        7: 'in če je šestdeset let in čez, moškega spola, bodi cenitev tvoja petnajst seklov, za žensko pa deset seklov.',
        8: 'Ako pa je ubožen za cenitev tvojo, naj ga postavijo pred duhovnika, da ga duhovnik oceni: po razmerju s tem, kar si obljubnik prisluži, naj ga duhovnik oceni.',
        9: 'Ako pa je živina, od katere se prinaša v darilo Gospodu, karkoli takega hoče kdo dati Gospodu, naj bode sveto.',
        10: 'Nikar naj tega ne premeni ali ne zameni, dobro za slabo ali slabo za dobro; če pa se kako zameni živina za drugo, bodi ona in njena zamena sveta.',
        11: 'Ako pa je katerakoli nečistih živali, od katerih se ne prinaša v darilo Gospodu, naj se postavi tista žival pred duhovnika,',
        12: 'in duhovnik naj jo oceni, je li dobra ali slaba; po tvoji cenitvi, duhovnik, naj velja.',
        13: 'Ako pa jo kdo hoče odkupiti, naj pridene peti del nad cenitev tvojo.',
        14: 'In če kdo posveti hišo svojo, da bodi sveta Gospodu, naj jo oceni duhovnik, ali je dobra ali slaba; kakor jo oceni duhovnik, tako bodi določeno.',
        15: 'In ako hoče hišo odkupiti tisti, ki jo je posvetil, naj pridene peti del denarja cenitve tvoje povrh, in hiša bodi njegova.',
        16: 'In če kdo posveti kaj polja posesti svoje Gospodu, bodi cenitev tvoja po tem, kolikor je ondi posevka: setev homera ječmena po petdeset seklov srebra.',
        17: 'Ako v začetku milostnega leta posveti njivo svojo, bodi določeno po cenitvi tvoji;',
        18: 'ako pa jo po milostnem letu posveti, naj mu duhovnik računi denar po številu let, kar jih je še do milostnega leta, in naj se odšteje od cenitve tvoje.',
        19: 'Ako pa hoče njivo tisti, ki jo je posvetil, odkupiti, naj pridene peti del denarja cenitve tvoje povrh, in njiva naj mu ostane;',
        20: 'ako pa ne odkupi njive ali če jo proda drugemu možu, se ne more več odkupiti,',
        21: 'in njiva ta, ko bo v milostnem letu oproščena, bodi sveta Gospodu, kakor njiva posvečena: duhovniku naj pripade v posest.',
        22: 'Ako pa posveti Gospodu njivo, ki jo je kupil, ki ni od dednega polja njegovega,',
        23: 'naj mu duhovnik računi znesek cenitve tvoje do milostnega leta, in on naj da, kolikor cene ti določiš, tisti dan kot sveto Gospodu.',
        24: 'V milostnem letu naj se povrne njiva spet tistemu, od kogar je bila kupljena, ki mu tudi gre kot posest.',
        25: 'In vsaka cenitev tvoja bodi po seklu svetišča: dvajset ger imej sekel.',
        26: 'Samo prvenca živine, ki se kot prvina daje Gospodu, naj nihče ne posvečuje: bodisi govedo ali drobnica, Gospodovo je že.',
        27: 'Ako pa je od nečiste živine, naj se odkupi po cenitvi tvoji in se pridene peti del povrh; in če se ne odkupi, naj to prodado po cenitvi tvoji.',
        28: 'Ali vsaka posvečena reč, ki bi jo kdo z zaroto posvetil Gospodu od vsega, kar je njegovega, bodisi iz ljudi ali iz živine ali ž njive posesti njegove, se ne sme prodati in ne odkupiti; karkoli je z zaroto posvečenega, presveto je Gospodu.',
        29: 'Vse posvečeno, kar se izmed ljudi z zaroto posveti, se ne sme odkupiti: mora se usmrtiti.',
        30: 'In vse desetine zemlje, od semena njive in od sadja dreves, so Gospodove: sveto je Gospodu.',
        31: 'Ako pa kdo hoče odkupiti kaj svojih desetin, naj pridene tega peti del.',
        32: 'In vse desetine od govedi in drobnice, od vsega, kar hodi pod pastirjevo palico, deseto bodi sveto Gospodu;',
        33: 'ni treba gledati, je li dobro ali slabo, tudi naj se ne zamenja; in če se vendarle zameni, bodi tisto sveto in zamena njegova sveta: ne sme se odkupiti.',
        34: 'To so zapovedi, ki jih je Gospod zapovedal Mojzesu za sinove Izraelove na gori Sinaju.',
    },
}
